WITH payload AS (SELECT $archive_payload$[{"id":"540bfe52-04ec-52b2-ab9b-27e60b28d6ea","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة مسجل وسماعات ومضخم صوت من داخل سيارة - مراقبة للسرقة -مشاركة يف سرقة -رجوع عن إقرار مصدق شرع ا -تعزير بالسجن واجللد.","document_number":"33453198","case_number":"33611773","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/14","year":"1434","subject":"سرقة -سرقة مسجل وسماعات ومضخم صوت من داخل سيارة - مراقبة للسرقة -مشاركة يف سرقة -رجوع عن إقرار مصدق شرع ا -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33453198 :‬تاريخه‪1433/11/14 :‬هـ‬\n                           ‫رقم الدعوى ‪33611773:‬‬\n            ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3443007‬تاريخه‪1434/2/20 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة مســجل وســماعات ومضخــم صــوت مــن داخــل ســيارة ‪-‬‬\n      ‫مراقبــة للســرقة ‪ -‬مشــاركة يف ســرقة ‪ -‬رجــوع عــن إقــرار مصــدق شــرع ًا‬\n                                                      ‫‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n      ‫‪-1‬مــا نقلــه ابــن قدامــة رحمــه اهلل مــن اإلجمــاع علــى أن حقــوق اهلل‬\n                ‫التــي ال تــدرأ بالشــبهات ال يقبــل رجــوع املقــر بإقــراره فيهــا‪.‬‬\n                ‫‪-2‬ما قرره السيوطي يف أشباهه أن التعزير يثبت مع الشبهة‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــى العــام ضــد املدعــى عليه باملشــاركة يف ســرقة مســجالت‬\n      ‫وســماعات مــن ســيارات وطلــب إثبــات اإلدانــة وتعزيــر املدعــى عليــه ‪،‬‬\n      ‫مت القبــض علــى املدعــى عليــه بعــد أن الحظــت إحــدى الدوريــات ســيارة‬\n      ‫يســتقلها املذكــور ومعــه آخريــن واســتدعى األمــر إلــى إيقــاف الســيارة‬\n      ‫وبتفيشــها عثــر معــه علــى مســجالت وســماعات وأداة لكســر الزجــاج‬\n      ‫وبعــد مراجعــة البالغــات اخلاصــة بالســرقة تبــن أن مــا يحــوزه املدعــى‬\n      ‫عليــه مــن املســروقات التــي مت اإلبــاغ عنهــا مســبقاً‪ ،‬أنكــر املدعــى‬\n      ‫عليــه للدعــوى ‪ ،‬وجــد إقــرار مصــدق شــرع ًا للمدعــى عليــه بصحــة‬\n      ‫الدعــوى ضــده ‪ -‬ثبــت إدانــة املدعــى عليــه مبوجــب إقــراره املصــدق‬\n\n‫‪199‬‬\n\f‫شــرعاً‪ ،‬حكمــت احملكمــة بتعزيــر املدعــى عليــه بالســجن واجللــد ‪،‬‬\n                              ‫صــدق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ ..........‬القاضــي باحملكمــة اجلزائيــة‬\n‫بالقطيــف بنــاء علــى املعاملــة احملالــة إلــي مــن فضيلــة الرئيــس برقــم‬\n‫‪ 33611773‬يف‪1433/10/18‬ه ـ والــواردة بكتــاب رئيــس دائــرة‬\n‫التحقيق واالدعاء العام مبحافظة القطيف ذي الرقم ه ق‪ 2701/2/4‬يف‬\n‫‪1433/10/17‬ه ـ حضــر املدعــي العــام ‪ ........‬مبوجــب كتــاب التكليف‬\n‫رقــم ه ـ ق ‪ 2156/2/4‬يف ‪1431/9/15‬ه ـ وادعــى علــى احلاضــر معــه‬\n‫ا يف دعــواه إنــه بتاريــخ‬‫‪ ...........‬الســعودي بالســجل املدنــي رقــم (‪ )....‬قائـ ً‬\n‫‪1433/2/8‬ه ـ قبــض علــى املدعــى عليه أثناء قيــام دورية البحث اجلنائي‬\n‫بشــرطة مركــز ‪ .....‬بعملهــا ومالحظتهــا لســيارة مــن نــوع (‪ )...‬موديــل‬\n‫(‪ ).....‬حتمــل اللوحــة رقــم (‪ )......‬كان يســتقلها املدعــى عليــه وبرفقتــه‬\n‫شــخصني املدعــو (‪ ).......‬واملدعــو (‪ )......‬فتــم االشــتباه بهــم وعنــد تفتيــش‬\n‫ســيارتهم مت العثــور علــى ثــاث مســجالت وخمــس ســماعات موجــودة‬\n‫داخــل الســيارة وأداة لكســر الزجــاج وبضبــط بــاغ ‪ ...../‬البالــغ مــن‬\n‫العمــر (‪ )26‬ســنة هنــدي اجلنســية مبوجــب رخصــة اإلقامــة رقــم (‪).......‬‬\n‫أفــاد بأنــه يف متــام الســاعة الرابعــة فجــر ًا مــن يــوم األحــد ‪1433/2/7‬ه ـ‬\n‫خــرج مــن منزلــه والحــظ بــأن الزجــاج األيســر اخللفــي لســيارته مكســور‬\n‫وقــد ســرق املســجل مــن داخــل الســيارة مــن نــوع ‪ .....‬حتمــل اللوحــة‬\n‫رقــم (‪ )......‬وبضبــط بــاغ املواطــن ‪ ..............‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم (‪ )...‬أفــاد بــأن مســجل ســيارته مــن نــوع (‪ )......‬لوحــة‬\n\n                                                                                         ‫‪200‬‬\n\f      ‫رقــم (‪ )..........‬قــد ســرق مــن داخلهــا عندمــا كانــت متوقفــة أمــام منزلــه‬\n      ‫وبضبــط بــاغ املواطــن‪ ...... /‬ســعودي اجلنســية مبوجــب ســجل مدنــي‬\n      ‫رقــم (‪ ).........‬أفــاد بــان زجــاج ســيارته مــن نــوع ‪ .....‬لوحــة رقــم (‪ )........‬قــد‬\n      ‫تعــرض للكســر وســرقة مســجل الســيارة وعــدد (‪ )8‬ســماعات خلفيــة‬\n      ‫وعــدد (‪ )2‬مضخــم صــوت وباســتجواب رفيقيــه املتهمــن بنفــس القضيــة‬\n      ‫(‪ ......‬و ‪ ).......‬أفــادا بــأن دور املدعــى عليــه أثنــاء ســرقه املســجل قيــادة‬\n      ‫الســيارة كمــا أقــرا بســرقة ســيارة مــن نــوع (‪).....‬وأقــرا بســرقة ‪ ....‬اللــون‬\n      ‫(‪ )......‬وباســتجواب املدعــى عليــه أقــر مبشــاركته يف ســرقة املســجالت‬\n      ‫مــن داخــل عــدد (‪ )3‬ثــاث ســيارات وأنــه كان يقــود الســيارة ودوره‬\n      ‫املراقبــة لزميليــه عنــد قيامهمــا بكســر زجــاج الســيارات والســرقة منهــا‬\n      ‫وقــد انتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى عليــه باملشــاركة‬\n      ‫يف ســرقة عــدد (‪ )3‬مســجالت وعــدد (‪ )5‬ســماعات صــوت مــن ثــاث‬\n      ‫ســيارات وحيــث أن مــا أقــدم عليــه املذكــور‪ ،‬وهــو بكامــل أهليتــه‬\n      ‫املعتبــرة شــرع ًا ‪ -‬فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا‬\n      ‫نســب إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجره وتردع غيــره (علم ًا بأن‬\n      ‫احلــق اخلــاص انتهــى بالتنــازل) هــذا مــا ادعــى بــه وبعرضــه علــى املدعــى‬\n      ‫ا مــا ذكــره املدعــي العــام يف دعــواه‬       ‫عليــه وبســؤاله عنــه أجــاب قائ ـ ً‬\n      ‫ضــدي مــن اتهامــي باملشــاركة يف الســرقة غيــر صحيــح والصحيــح‬\n      ‫أنــي كنــت راكب ـ ًا مــع املذكوريــن لغــرض إيصالــي ولــم أكــن أعلــم‬\n      ‫بقيامهمــا بالســرقة وال حتــى برغبتهمــا فيهــا هــذا مــا أجــاب بــه وبســؤال‬\n      ‫ا بينتــي مــا جــاء‬ ‫املدعــي العــام عــن بينتــه علــى طبــق دعــواه أجــاب قائ ـ ً‬\n      ‫يف أوراق املعاملــة وبالرجــوع إلــى أوراق املعاملــة جــرى االطــاع علــى‬\n      ‫اعتــراف املدعــى عليــه املصــدق شــرع ًا املــدون علــى الصحيفــة رقــم ‪4‬‬\n\n\n‫‪201‬‬\n\f‫مــن ملــف التحقيــق املرفــق باملعاملــة باللفــة رقــم ‪ 1‬ويتضمــن مــا عطفــه‬\n‫املدعــي العــام مــن اســتجواب للمدعــى عليــه وبعرضــه علــى املدعــى عليــه‬\n‫ا إننــي لــم أقــم بقيــادة الســيارة ولــم أقــم باملراقبــة للمذكوريــن‬‫أفــاد قائـ ً‬\n‫لكونــي لــم أكــن أعلــم بقيامهــم بالســرقة ومــا ذكــر يف اعتــرايف غيــر‬\n‫صحيــح هــذا مــا أجــاب بــه فجــرى إفهامــه بأنــه جــرى تصديــق إقــراره‬\n‫عنــد فضيلــة قاضــي األحــداث فأفــاد مبــا أفــاد بــه فبنــاء علــى مــا تقــدم‬\n‫مــن الدعــوى واإلجابــة وإلنــكار املدعــى عليــه مــا نســبه لــه املدعــي العــام‬\n‫وملــا جــاء يف إقــرار املدعــى عليــه املصــدق شــرع ًا مــن قيامــه باملراقبــة يف‬\n‫جرميــة الســرقة وألنــه أقــر مبــا يوجــب تعزيــر ًا و عدولــه عنــه غيــر مقبــول‬\n‫وقــد نقــل ابــن قدامــة رحمــه اهلل اإلجمــاع علــى أن حقــوق اهلل التــي ال‬\n‫تــدرأ بالشــبهات ال يقبــل رجــوع املقــر بإقــراره فيهــا وألن التعزيــر يثبت مع‬\n‫الشــبهة ملــا قــرره الســيوطي رحمــه اهلل يف أشــباهه وحلداثــة ســن املدعــى‬\n‫عليــه ولعــدم وجــود ســوابق جنائيــة عليــه لــذا وجلميــع مــا تقــدم فقــد ثبــت‬\n‫لــدي مراقبــة املدعــى عليــه يف جرميــة الســرقة وقــررت تعزيــره بجلــده‬\n‫تســعني جلــدة مفرقــة علــى دفعتــن كل دفعــة عــدد خمســة وأربعــن‬\n‫جلــدة بــن كل دفعــة وأخــرى مــدة أســبوعني وســجنه مــدة شــهرين‬\n‫يحتســب منهــا مــدة إيقافــه بســبب هــذه القضيــة ومبــا ذكــر حكمــت‬\n‫وبعــرض احلكــم علــى الطرفــن اعترضــا عليــه وطلبــا اســتئنافه دون‬\n‫تقــدمي الئحــة اعتراضيــة مــن املدعــي العــام ومــع تقــدمي الئحــة اعتراضيــة‬\n‫مــع املدعــى عليــه وجــرى تســليمه صــورة مــن إعــام احلكــم هــذا اليــوم‬\n‫وجــرى إفهامــه بــأن لــه مــدة ثالثــن يومـ ًا لتقــدمي الئحــة اعتراضــه وأنه إذا‬\n‫لــم يقدمهــا خاللهــا فســيتم بعــث كامــل املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم خــال خمســة وأربعــن يومـ ًا مــن تأريــخ النطــق بــه بنــاء‬\n\n\n                                                                                          ‫‪202‬‬\n\f      ‫علــى املــادة اخلامســة والتســعني بعــد املائــة مــن نظــام اإلجــراءات اجلزائيــة‬\n      ‫ففهمــه وللبيــان حــرر يف ‪1433/11/14‬ه ـ وصلــى اهلل وســلم علــى نبينــا‬\n                                              ‫محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد لقــد عــادت املعاملــة مــن محكمــة االســتئناف‬\n      ‫بالدمــام بكتــاب فضيلــة رئيســها رقــم ‪ 34132343‬يف ‪1434/2/26‬ه ـ‬\n      ‫املقيــدة يف هــذه احملكمــة برقــم ‪ 34531938‬يف ‪1434/3/1‬هـ واحملالة‬\n      ‫مــن فضيلــة الرئيــس وبرفقهــا إعــام احلكــم الصــادر منــي برقــم‬\n      ‫‪ 33453198‬يف ‪1433/11/14‬ه ـ وبرفقهــا قــرار أصحــاب الفضيلــة‬\n      ‫قضــاة الدائــرة اجلزائيــة االولــى رقــم ‪ 3443007‬يف ‪1434/2/20‬ه ـ‬\n      ‫ونصــه بعــد املقدمــة وبدراســة القــرار وصــورة ضبطــه واوراق املعاملــة‬\n      ‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/2/19‬ه ـ قاضــي اســتئناف د‪.‬‬\n      ‫‪...........‬ختمــه وتوقيعــه قاضــي اســتئناف ‪.............‬ختمــه وتوقيعــه رئيــس‬\n      ‫الدائــرة ‪ .......‬ختمــه وتوقيعــه أ‪ .‬ه ـ وللبيــان حرر يف ‪1434/3/2‬هـ وصلى‬\n                    ‫اهلل وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن ‪.‬‬\n\n\n\n\n‫‪203‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":199,"source_page_end":203,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ef5906b3004fa213584247a1df06e16460f4200ace368e6987fa99cc835ccc91","normalized_text_hash":"95824540f093689cd616f2ffd3318d0479029f21d686739a5296ab3e88d00bea","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p199-33453198"},{"id":"c2c4b14e-11ca-5300-b6e9-736e95092ae1","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة أغنام -قيام راعي بالسرقة -قص شبك أغنام وكسر باب شبك للسرقة -تعرف على املسروق من قبل صاحبه -عدم ثبوت إدانة -إخاء سبيل -تخلف أحد املدعى عليهم باحلضور.","document_number":"33438406","case_number":"33615824","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/10/25","year":"1434","subject":"سرقة -سرقة أغنام -قيام راعي بالسرقة -قص شبك أغنام وكسر باب شبك للسرقة -تعرف على املسروق من قبل صاحبه -عدم ثبوت إدانة -إخاء سبيل -تخلف أحد املدعى عليهم باحلضور.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 33438406:‬تاريخه ‪1433/10/25:‬هـ‬\n                    ‫رقم الدعوى ‪33615824:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n             ‫‪ 3438556‬تاريخه‪1434/2/17 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة أغنام ‪ -‬قيام راعي بالســرقة ‪ -‬قص شــبك أغنام وكســر‬\n‫بــاب شــبك للســرقة ‪ -‬تعــرف علــى املســروق مــن قبــل صاحبــه ‪ -‬عــدم‬\n   ‫ثبــوت إدانــة ‪ -‬إخــاء ســبيل ‪ -‬تخلــف أحــد املدعــى عليهــم باحلضــور‪.‬‬\n\n\n\n\n                                                        ‫األصل براءة الذمة ‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد خمســة أشــخاص يحملــون بطاقــات بديلــة حضــر‬\n‫منهــم أربعــة وتخلــف خامــس عــن احلضــور ومت ســماع الدعــوى ضــد مــن‬\n‫حضــر‪ ،‬ادعــى املدعــى العــام بــان املدعــى عليهــم اخلمســة قامــوا بســرقة‬\n‫مجموعــة أغنــام مــن حظيــرة‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند‬\n‫إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة ‪ ،‬مت القبــض علــى املدعــى عليهــم‬\n‫ـاء علــى شــكوى مــن أحــد األشــخاص عــن تعرضــه لســرقة أغنامــه‬          ‫بنـ ً‬\n‫مــن حوشــه ويتهــم أحــد املدعــى عليهــم الــذي كان يعمــل لديــه‪ ،‬مت‬\n‫االشــتباه باملدعــى عليهــم وعرضهــم علــى املبلــغ فاســتطاع التعــرف علــى‬\n‫أحــد املدعــى عليهــم الــذي كان يعمــل عنــده قبــل الســرقة بيــوم واحــد‪،‬‬\n‫إنــكار املدعــى عليهــم‪ ،‬لــم تثبــت اإلدانــة يف حــق املدعــى عليهــم األربعــة‬\n‫احلاضريــن واخلــي ســبيلهم مــن الدعــوى‪ -‬محاكمــة املدعــى عليــه‬\n\n                                                                                     ‫‪204‬‬\n\f      ‫اخلامــس حــن حضــوره‪ ،‬مت تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n      ‫اجلزائيــة‬\n         ‫ّ‬        ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ........‬القاضــي يف احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائية يف محافظة االحساء برقم ‪ 33615824‬وتاريخ ‪1433/10/22‬هـ‬\n      ‫املقيــدة باحملكمــة برقــم ‪ 331860550‬وتاريــخ ‪ 1433/10/22‬ه ـ ففــي‬\n      ‫يــوم األحــد املوافــق‪ 1433/10/22‬ه ـ افتتحــت اجللســة األولــى الســاعة‬\n      ‫العاشــرة وخمســة عشــر دقيقــة وفيهــا حضــر املدعــي العــام ‪ ......‬املعمــد‬\n      ‫بالترافــع أمــام هــذه احملكمــة مبوجــب خطــاب ســعادة رئيــس دائــرة‬\n      ‫التحقيــق واالدعــاء العــام مبحافظــة االحســاء ذي الرقــم ه ـ ق ‪137/2/2‬‬\n      ‫والتاريــخ ‪1431/1/5‬ه ـ واحضــر معــه كل مــن ‪ .........‬مينــي اجلنســية‬\n      ‫مبوجــب البطاقــة البديلــة رقــم ‪/9/21‬ش خ‪........ 1380/‬مينــي اجلنســية‬\n      ‫مبوجــب البطاقــة البديلــة رقــم ‪/9/21‬ش خ ‪ 1619 /‬و ‪........‬مينــي اجلنســية‬\n      ‫مبوجــب البطاقــة البديلــة رقــم ‪/9/21‬ش خ ‪ 1618/‬و ‪ ..........‬مينــي‬\n      ‫اجلنســية مبوجــب البطاقــة البديلــة رقــم ‪/9/21‬ش خ ‪ 1617/‬وتخلــف‬\n      ‫املدعــى عليــه الرابــع املدعــو ‪ .......‬عــن احلضــور وادعــى املدعــي العــام‬\n      ‫قائــا يف دعــواه أنــه بتاريــخ ‪1432/4/1‬ه ـ ورود بــاغ لرجــل الدوريــات‬\n      ‫األمنيــة مــن املوطــن‪ ......... /‬مفــاده تعــرض شــبك أغنامــه للســرقة وســرق‬\n      ‫منــه عــدد (‪ )160‬مائــة وســتون رأس مــن األغنــام وباالنتقــال للموقــع‬\n      ‫اتضــح أن الشــبك قــد مت قصــه وأن بــاب الشــبك مكســور وبعــرض مــا‬\n      ‫عــدده (‪ )29‬مــن األغنــام علــى املبلــغ أفــاده بأنهــا تعــود لــه ومــن أغنــام‬\n      ‫التــي مت ســرقها وبعــرض املدعــى عليهــم علــى املبلــغ تعــرف املبلــغ علــى‬\n\n‫‪205‬‬\n\f‫املدعــى عليــه الرابــع وأفــاد بأنــه قــام بالعمــل لديــه قبــل ســرقة األغنــام‬\n‫بيــوم واحــد وباســتجواب املدعــى عليــه األول أقــر بأنــه كان يعمــل راعــي‬\n‫غنــم لــدى املواطنــة‪ ....... /‬وقــام بســرقة مــا عــدده (‪ )115‬مــن األغنــام‬\n‫وبيعهــا علــى املدعــى عليــه اخلامــس وباســتجواب املدعــى عليــه الثانــي‬\n‫أفــاد بأنــه قــام بعمــل شــبك لألغنــام املســروقة بطلــب مــن املدعــى عليــه‬\n‫اخلامــس دون علمــه أنهــا مســروقة وباســتجواب املدعــى عليــه اخلامــس‬\n‫أفــاد بأنــه قــام بشــراء مجموعــة أغنــام مــن املدعــى عليــه االول وال يعلــم‬\n‫بأنهــا مســروقة وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لهــم بســرقة‬\n‫مجموعــة أغنــام مــن حظيــرة املبلــغ وذلــك لألدلــة والقرائــن التاليــة ‪-1-:‬‬\n‫محضــر االنتقــال واملعاينــة املنــوه عنــه واملــدون علــى الصفحــة رقــم (‪)3-2‬‬\n‫مــن دفتــر التحقيــق لفــة رقــم (‪ -2- )1‬مــا جــاء يف اقــوال املبلــغ املدونــة‬\n‫علــى الصفحــة رقــم (‪ )1‬مــن دفتــر التحقيــق لفــة رقــم (‪ -3- )1‬مــا جــاء‬\n‫يف محضــر التعــرف علــى االغنــام املدونــة علــى الصفحــة رقــم (‪ )10‬مــن‬\n‫دفتــر التحقيــق لفــة رقــم (‪ -4- )1‬مــا جــاء يف محضــر التعــرف علــى‬\n‫املدعــى عليــه الرابــع املدونــة علــى الصفحــة رقــم (‪ )15‬مــن دفتــر التحقيق‬\n‫لفــه رقــم (‪ )57‬وبالبحــث عمــا إذا كان عليهــم ســوابق لــم يعثــر لهــم علــى‬\n‫ســوابق مســجلة وحيــث إن مــا أقــدم عليــه املدعــى عليهــم وهــو بكامــل‬\n‫أهليتهــم املعتبــرة شــرعا فعــل محــرم ومعاقــب عليــه شــرعا لــذا أطلــب‬\n‫إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة رادعــة لهــم‬\n‫وزاجــرة لغيرهــم لقــاء مــا اســند إليهــم مــن اتهــام (علمــا أن احلــق اخلــاص‬\n‫مــازال قائــم ) هــذه دعــواي و قــد اطلعــت علــى القــرار الصــادر مــن هــذه‬\n‫احملكمــة برقــم ‪ 33183041‬والتاريــخ ‪1433/4/11‬ه ـ املكتســب‬\n‫القطعيــة بتأييــده وتصديقــه بقــرار محكمــة االســتئناف ذي الرقــم‬\n\n\n                                                                                       ‫‪206‬‬\n\f      ‫‪ 33317170‬والتاريــخ ‪1433/6/28‬ه ـ املتضمــن كــون النظــر يف هــذه‬\n      ‫الدعــوى مــن اختصــاص املكتــب القضائــي الثامــن وبنــاء عليــة فقــد‬\n      ‫قــررت النظــر يف هــذه الدعــوى وبعــرض الدعــوى علــى املدعــى عليــه‬\n      ‫األول ‪ ......‬أجــاب قائــا مــا ذكــره املدعــي العــام غيــر صحيــح فلــم اســرق‬\n      ‫أغنــام ‪ ...‬وال صلــة لــي بهــا وال ادري مــن الســارق هكــذا أجــاب وبعــرض‬\n      ‫الدعــوى علــى املدعــى عليــه الثانــي ‪ ......‬أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫العــام غيــر صحيــح فلــم اســرق هــذه األغنــام هكــذا أجــاب وبعــرض‬\n      ‫الدعــوى علــى املدعــى عليــه الثالــث ‪ ......‬أجــاب قائــا مــا ذكــره املدعــي‬\n      ‫العــام غيــر صحيــح فلــم اســرق هــذه األغنــام هكــذا أجــاب وبعــرض‬\n      ‫الدعــوى علــى املدعــى عليــه الرابــع ‪ .......‬أجــاب قائــا ماذكــره املدعــي‬\n      ‫العــام غيــر صحيــح فلــم اســرق هــذه األغنــام هكــذا أجــاب وقــد قــرر‬\n      ‫كل مــن املدعــى عليهــم قائــا إن املدعــى عليــه اخلامــس ‪ .......‬أفــرج عنــه‬\n      ‫منــذ ســتة أشــهر وال نــدري عنــه هكــذا قــرر كل منهــم وبســؤال املدعــي‬\n      ‫العــام عــن بينتــه قــرر قائــا بينتــي مــا ذكرتــه أعــاه واطلــب الرجــوع‬\n      ‫إليــه هكــذا قــرر وبالرجــوع إليــه اطلعــت علــى محضــر االنتقــال الســريع‬\n      ‫واملعاينــة األوليــة املــدون علــى الصفحتــن ‪ 2.3‬مــن اللفــة االولــى وأقــوال‬\n      ‫املبلــغ املدونــة علــى الصفحــة األولــى مــن اللفــة األولــى فوجدتهــا تتضمــن‬\n      ‫مــا ذكــره املدعــي العــام كمــا تضمنــت اتهــام املدعــي يف احلــق اخلــاص‬\n      ‫‪..........‬حلــارس مينــي ‪ ....‬بســرقة هــذه األغنــام كمــا اطلعــت علــى محضــر‬\n      ‫التعــرف علــى األغنــام املــدون علــى الصفحــة العاشــرة مــن اللفــة األولــى‬\n      ‫فوجدتــه يتضمــن اســتالم املدعــي باحلــق اخلــاص تســعة وعشــرون رأس‬\n      ‫مــن األغنــام عــن طريــق البحــث اجلنائــي التابــع لشــرطه منطقــة الريــاض‬\n      ‫عقــب القبــض علــى ‪..........‬ورفقــاه بعــد تعرفــه علــى تلــك األغنــام وأنهــا‬\n\n\n‫‪207‬‬\n\f‫مــن جملــة الغنــم املســروقة البالــغ عددهــا مائــة وتســعة وســتون رأس‬\n‫مــن حظيــرة والدتــه الواقعــة يف حــي ‪ ......‬كمــا اطلعــت علــى الصفحــة‬\n‫اخلامســة عشــرة مــن اللفــة ‪ 57‬فوجدتهــا تتضمــن محضــر عــرض املدعــى‬\n‫عليهــم علــى أنظــار املدعــي باحلــق اخلــاص ‪.....‬وكــون املدعــي باحلــق‬\n‫اخلــاص‪ .....‬تعــرف علــى املدعــى عليــه الرابــع ‪........‬الــذي قــام بالعمــل‬\n‫لــدى ‪ .....‬قبــل ســرقة األغنــام بيــوم واحــد وبعرضهــا علــى املدعــى عليهــم‬\n‫قــرر كل منهــم قائــا ال صلــة لــي بســرقة هــذه األغنــام ولــم اكســر‬\n‫بــاب الشــبك ولــم أقــم بقصــه ولــم اســرق غنمــا هكــذا قــرر كل منهــم‬\n‫وأضــاف املدعــى عليــه الرابــع قائــا لــم اعمــل لــدى ‪ .........‬وال ادري عــن‬\n‫ســبب اتهامــه لــي هكــذا قــرر كمــا أضــاف املدعــى عليــه األول قائــا‬\n‫ال صلــة لســرقتي ألغنــام ‪ .....‬بهــذه القضيــة وقــد حكــم علــي بســجني‬\n‫ســنة وثالثــة أشــهر يف احلــق العــام هكــذا أضــاف كمــا أضــاف املدعــى‬\n‫عليــه الثانــي قائــا لــم اعمــل شــبكا األغنــام وإمنــا عملتــه يف قضيــة‬\n‫أخــرى بأجــرة مــن ‪ ....‬وعمتــه الســهلية مببلــغ مئــة ريــال يف قضيــة أخــرى‬\n‫ال صلــة لهــا بهــذه الدعــوى مــن غيــر علــم منــي بكــون تلــك األغنــام‬\n‫مســروقة وقــد حكــم يف تلــك القضيــة بإخــاء ســبيلي بعــدم ثبــوت‬\n‫الدعــوى هكــذا أضــاف وبســؤال املدعــي العــام هــل لديــة زيــادة بينــه‬\n‫قــرر قائــا ليــس لــدي ســوى مــا قدمــت هكــذا قــرر وقــد اطلعــت علــى‬\n‫القــرار الصــادر مــن هــذا املكتــب بهــذه احملكمــة برقــم ‪33155156‬‬\n‫وتاريــخ ‪1433/3/26‬ه ـ املتضمــن احلكــم علــى املدعــى عليــه األول ‪.......‬‬\n‫بســجنه ملــدة ســنه وثالثــة أشــهر وجلــده مائــة وخمســن جلــده علــى النحــو‬\n‫املوضــح يف القــرار كمــا تضمــن عــدم ثبــوت الدعــوى ضــد كل مــن ‪......‬‬\n‫و ‪ ....‬و‪ ......‬وإخــاء ســبيل كل منهــم كمــا تضمــن عقوبــة املدعــى عليــه‬\n\n\n                                                                                    ‫‪208‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":204,"source_page_end":208,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"6b5111c7c56021f8d7002272732312c46833138039a7933b8c9b62cfe1750963","normalized_text_hash":"74cf92f70975923b9024de16d58b45b50c88ae38fcc8cb1333e63ca8dcb933e2","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p204-33438406"},{"id":"c4dfccfc-a331-5cf6-ab90-213e960f9bfa","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -حدث -جتول يف سيارة مسروقة -إخفاء سيارة مسروقة -مشاركة يف سرقة -تخطيط يف سرقة -إحداث تلفيات -هروب من السلطة -قيادة سيارة مسروقة -تعزير بالسجن","document_number":"33438692","case_number":"33618702","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/10/25","year":"1434","subject":"سرقة -سرقة سيارة -حدث -جتول يف سيارة مسروقة -إخفاء سيارة مسروقة -مشاركة يف سرقة -تخطيط يف سرقة -إحداث تلفيات -هروب من السلطة -قيادة سيارة مسروقة -تعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك ‪ 33438692:‬تاريخه ‪1434/10/25:‬هـ‬\n                          ‫رقم الدعوى ‪33618702:‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3436999‬تاريخه‪1434/2/13 :‬هـ‬\n\n\n\n      ‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬حــدث ‪ -‬جتــول يف ســيارة مســروقة ‪ -‬إخفــاء‬\n      ‫ســيارة مســروقة ‪ -‬مشــاركة يف ســرقة ‪ -‬تخطيــط يف ســرقة ‪ -‬إحــداث‬\n      ‫تلفيات ‪ -‬هروب من الســلطة ‪ -‬قيادة ســيارة مســروقة ‪ -‬تعزير بالســجن‬\n                                                                    ‫واجللــد‪.‬‬\n\n\n\n\n                   ‫‪-1‬التعزير مشروع يف كل معصية ال حد فيها وال كفارة‪.‬‬\n      ‫‪-2‬مــا جــاء يف كتــاب كشــاف القنــاع لإلمــام البهوتــي يف ‪ 14‬ص ‪49‬‬\n      ‫بعــد أن ســاق جملــة مــن موجبــات التعزيــر قــال مــا نصــه ( الســرقة فيمــا‬\n                                                                      ‫ال قطــع فيــه)‪.‬‬\n\n\n\n\n      ‫دعــوى املدعــى العــام ضــد ثالثــة أشــخاص بتهمــة االشــتراك يف ســرقة‬\n      ‫ســيارة والتجــول بهــا وإخفائهــا والتخطيــط ســوي ًا لذلــك واالصطــدام‬\n      ‫بســيارة أخــرى كانــت متوقفــة والهــروب مــن املوقــع‪ ،‬وطلــب املدعــي‬\n      ‫العــام اثبــات مــا أســند إليهــم و احلكــم عليهــم بعقوبــة تعزيريــه ‪ ،‬مت‬\n      ‫القبــض علــى املدعــى عليهــم بعــد وقــوع حــادث مــروري بــن ســيارتني‬\n      ‫إحداهمــا املســروقة ‪ ،‬حيــث كان املدعــى عليهــم بداخلهــا يقودهــا‬\n      ‫أحدهــم ‪ ،‬ثــم هربــوا بعــد وقــوع احلــادث ثــم عــاد أحدهــم بعــد أن نســي‬\n‫‪211‬‬\n\f‫حذائــه فتــم القبــض عليــه و بعــد ذالــك مت القبــض علــى رفيقيــه بعــد أن‬\n‫قــام بداللــة الســلطات األمنيــة عليهمــا ‪ ،‬أقــر املدعــى عليهــم بالدعــوى‪،‬‬\n‫حكمــت احملكمــة بتعزيــر املدعــى عليهــم بالســجن واجللــد ‪ ،‬مت‬\n                           ‫تصديــق احلكــم مــن محكمــة االســتئناف ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ......‬القاضــي يف احملكمــة اجلزائيــة‬\n‫باملدينــة املنــورة واملكلــف بنظــر قضايــا األحــداث وبنــاء علــى املعاملــة‬\n‫احملالــة لنــا مــن فضيلــة رئيــس احملكمــة اجلزائيــة باملدينــة املنــورة برقــم‬\n‫‪ 33618702‬وتاريــخ ‪1433/10/23‬ه ـ املقيــدة باحملكمــة برقــم‬\n‫‪ 331872143‬وتاريــخ ‪1433/10/23‬ه ـ ففــي يــوم األربعــاء‬\n‫املوافق‪1433/10/25‬ه ـ افتتحــت اجللســة الســاعة ‪ 10 : 00‬وفيهــا حضــر‬\n‫املدعــي العــام بهيئــة التحقيــق واالدعــاء العــام باملدينــة املنــورة ‪ ......‬وادعــى‬\n‫علــى احلاضريــن معــه يف مجلــس احلكــم األحــداث ‪ ......-1 :‬تشــادي‬\n‫اجلنســية مبوجــب اإلقامــة الصــادرة مــن جــوازات املدينــة املنــورة برقــم‬\n‫(‪ )....‬واحلــدث ‪ ........-2‬تشــادي اجلنســية مبوجــب اإلقامــة الصــادرة مــن‬\n‫جــوزات املدينــة املنــورة برقــم (‪ )......‬واحلــدث ‪ .........-3‬تشــادي اجلنســية‬\n‫ا‬\n‫مبوجــب اإلقامــة الصــادرة مــن جــوزات املدينــة املنــورة برقــم (‪ )......‬قائـ ً‬\n‫يف حتريــر دعــواه إنــه بتاريــخ ‪1433 /08/9‬ه ـ تســلمنا محضــر دوريــات‬\n‫األمــن رقــم ( ‪ )21280‬وبرفقــة املدعــي‪ .......‬ســعودي اجلنســية واملدعــى‬\n‫عليــه‪ ......‬تشــادي اجلنســية وقــد تضمــن احملضــر أنــه أثنــاء عمــل الدوريــة‬\n‫األمنيــة يف الدائــري الثانــي الحظــت وقــوع حــادث مــروري بــن ســيارتني‬\n‫األولــى مــن نــوع ‪ ....‬لوحــة رقــم (‪ ).... ...‬تعــود ملكيتهــا للمدعــي واألخــرى‬\n\n                                                                                            ‫‪212‬‬\n\f      ‫مــن نــوع ‪ ...‬لوحــة رقــم (‪ ).......‬ولوحــظ أن قائــد الســيارة ‪ ......‬قــد هــرب‬\n      ‫مــن املوقــع وســلم احلــادث لدوريــة املــرور وأثنــاء التســليم حضــر املدعــى‬\n      ‫عليــه ‪ .....‬حــايف القدمــن يبحــث عــن حذائــه يف الســيارة ومت القبــض‬\n      ‫عليــه مــن قبــل دوريــات األمــن ومــن ثــم حضــر املدعــي وأفــاد أن الســيارة‬\n      ‫‪ .....‬تعــود ملكيتهــا لــه وأنهــا ســرقت مــن أمــام منزلــه واتضــح أن ‪.......‬‬\n      ‫هــو مــن يقــود الســيارة ‪ ........‬املســروقة عنــد وقــوع احلــادث ومت ســحب‬\n      ‫الســيارات إلــى حجــز املــرور وتســليم املدعــي املدعــى عليــه ملركــز‬\n      ‫شــرطة ‪ ......‬وبســماع أقــوال ‪ ......‬ذكــر أنــه بتاريــخ ‪ 1433/08/29‬ه ـ‬\n      ‫عنــد حوالــي الســاعة الرابعــة فجــر ًا أخبــره ابنــه ‪ .....‬أنــه شــاهد ســيارته‬\n      ‫مــن نــوع ‪ ......‬لوحــة رقــم (‪ ).... ...‬مصدومــة علــى طريــق الدائــري الثانــي‬\n      ‫وأضــاف أنــه كان قــد أوقــف ســيارته يف املســاء أمــام منزلــه يف حــي ‪......‬‬\n      ‫وهــي ســليمة ولــم يقــم بإعطائهــا أحــد ويدعــي أنهــا ســرقت مــن أمــام‬\n      ‫منزلــه ويتهــم الشــخص الــذي مت القبــض عليــه مــن قبــل الدوريــات األمــن‬\n      ‫جــوار الســيارة بعــد احلــادث والــذي اتضــح لــه فيمــا بعــد أنــه يدعــى‪.....‬‬\n      ‫وباســتجواب املدعى عليه ‪ .....‬أفاد أنه بتاريخ ‪1433/08/29‬هـ الســاعة‬\n      ‫الواحــدة صباح ـ ًا كان يجلــس يف حديقــة ‪ ......‬الواقعــة يف حــي ‪.....‬‬\n      ‫واتصــل عليــه صديقــه املدعــى عليــه‪ ......‬وســأله عــن مــكان تواجــده‬\n      ‫فأخبــره أنــه يف احلديقــة فحضــر لــه وكان برفقتــه املدعــى عليــه ‪......‬‬\n      ‫وميتطــون ســيارة مــن نــوع ‪ ......‬يقودهــا ‪ .....‬وبعــد ركوبــه معهــم أخبــره‬\n      ‫‪ ......‬أن الســيارة مســروقة هــو مــن قــام بســرقتها وتوجهــوا إلــى اســتراحة‬\n      ‫يف طريــق ‪ .....‬يف ‪ .....‬مســتأجرة تلــك الليلــة مــن قبــل أصدقائهــم يف احلــي‬\n      ‫وقبيــل وصولهــم لالســتراحة قامــوا بإخفــاء الســيارة بــن األشــجار لكي‬\n      ‫ال يشــاهدها أصحابهــم ومكثــوا عــدة دقائــق عنــد االســتراحة ثــم عــادوا‬\n\n\n‫‪213‬‬\n\f‫للســيارة وركبــوا بهــا وقــام هــو بقيادتهــا وتوجهــوا إلــى حــي ‪ ......‬يريــدون‬\n‫إعــادة الســيارة إلــى املوقــع الــذي ســرقوها منــه وعنــد وصولهــم إلــى‬\n‫طريــق الدائــري الثانــي مقابــل مجمــع ‪ .....‬التجــاري وقــع لهــم حــادث‬\n‫مــروري حيــث انحرفــت بهــم الســيارة واصطدمــت بســيارة أخــرى مــن‬\n‫نــوع ‪ .....‬كانــت متوقفــة بجانــب الطريــق ثــم نزلــوا مــن الســيارة وهربــوا‬\n‫جميعـ ًا وعــاد هــو للموقــع ألخــذ جوالــه مــن نــوع ‪ ....‬الــذي ســقط منــه يف‬\n‫الســيارة أثنــاء احلــادث فتــم القبــض عليــه مــن قبــل دوريــات األمــن‬\n‫وباستجواب احلدث ‪ ....‬أفاد بأنه يف يوم الثالثاء املوافق ‪1433/08/27‬هـ‬\n‫عثــر علــى مفتــاح ســيارة ســاقطا علــى األرض جــوار بقالــة آيســكرمي ‪.....‬‬\n‫يف حــي ‪ ....‬الــذي يســكن بــه وذهــب إلــى حديقــة ‪ ......‬يف احلــي ذاتــه‬\n‫وتقابــل مــع صديقــه ‪ ......‬وأخبــره عــن املفتــاح وطــرح عليــه فكــرة ســرقة‬\n‫أي ســيارة واتفقــا ســوي ًا علــى ســرقة أي ســيارة علــى أن تكــون الســرقة‬\n‫فجــر اخلميــس لكــي يذهبــوا علــى الســيارة املســروقة إلــى اســتراحة تقــع‬\n‫يف طريــق ‪ ......‬سيســتأجرها بعــض أصدقائهــم يف احلــي تلــك الليلــة وعنــد‬\n‫حوالــي الســاعة الواحــدة مــن فجــر يــوم اخلميــس املوافــق ‪1433 /8/29‬هـ‬\n‫تقابــل مــع صديقــه املدعــى عليــه ‪ .......‬حســب االتفــاق جــوار احلديقــة‬\n‫وكان يرتــدي بجامــة نــوم بنيــة اللــون ويرتــدي صديقــه ‪ .....‬بنطــال أســود‬\n‫وفانيلــة تشــبه بلونهــا فانيلــة نــادي ‪ .......‬وقامــوا بالبحــث عــن أي ســيارة‬\n‫ا معــه مفتــاح الســيارة الــذي وجــده علــى األرض ســابق ًا‬       ‫لســرقتها حام ـ ً‬\n‫ووجــدوا ســيارة مــن نــوع ‪ ......‬متوقفــة جــوار أحــد املنــازل يف حــي ‪....‬‬\n‫فحــاول هــو فتــح بــاب الســيارة باملفتــاح لكنــه لــم يســتطع ثــم حــاول‬\n‫صديقــه ‪ ......‬فتــح الســيارة باملفتــاح فلــم يســتطع فعــاود هــو احملاولــة‬\n‫ففتــح الســيارة باملفتــاح وقــام بتشــغيلها باملفتــاح ذاتــه وقــام‪ .......‬بقيــادة‬\n\n\n                                                                                         ‫‪214‬‬\n\f      ‫الســيارة وركــب هــو معــه واتصــل ‪ .......‬علــى صديقــه ‪ .......‬وأخبرهــم‬\n      ‫أنهــم قامــوا بســرقة ســيارة وذهبــوا لــه عنــد احلديقــة وركــب ‪ ......‬معهــم‬\n      ‫وتوجهــوا لالســتراحة الواقعــة يف طريــق املطــار يف ‪ .....‬وقبــل وصولهــم‬\n      ‫لالســتراحة قامــوا بإخفــاء الســيارة بــن األشــجار كــي ال يشــاهدها‬\n      ‫أصدقائهــم ومكثــوا عنــد االســتراحة عــدة دقائــق ثــم عــادوا للســيارة‬\n      ‫وركبــوا بهــا يريــدون العــودة للحــي وبطريــق العــودة كان يقــود الســيارة‬\n      ‫‪ ......‬وعنــد وصولهــم لطــرق الدائــري الثانــي علــى طريــق اخلدمــة مــن‬\n      ‫اجلهــة األخــرى املقابلــة ملجمــع ‪ ......‬التجــاري انحرفــت بهــم الســيارة‬\n      ‫واصطدمــوا بســيارة مــن نــوع ‪ .....‬كانــت متوقفــة ونزلــوا مــن الســيارة‬\n      ‫وهربــوا جميع ـ ًا ثــم عــاد ‪ .....‬إلــى املوقــع للبحــث عــن جوالــه الــذي فقــده‬\n      ‫يف الســيارة ومت القبــض عليــه وباســتجواب احلــدث‪ .......‬أفــاد بأنــه يف يــوم‬\n      ‫الثالثــاء املوافــق ‪1433/08/27‬ه ـ كان يجلــس يف حديقــة ‪ ....‬وحضــر‬\n      ‫لــه صديقــه ‪ ......‬وأخبــره أنــه وجــد مفتــاح ســيارة ســاقط علــى األرض‬\n      ‫وطــرح عليــه فكــرة ســرقة ســيارة واتفقــا ســوي ًا علــى ســرقة أي ســيارة‬\n      ‫لكــي يذهبــوا عليهــا إلــى اســتراحة تقــع يف طريــق ‪ .......‬سيســتأجرها‬\n      ‫بعــض أصدقائهــم يــوم اخلميــس علــى أن يعيــدوا الســيارة بعــد ذلــك إلــى‬\n      ‫موقعهــا ويف مســاء يــوم األربعــاء املوافــق ‪1433/08/28‬ه ـ تقابــل مــع‬\n      ‫صديقــه ‪ ...... /‬حســب االتفــاق وكان يرتــدي حينهــا بنطــاال أســود‬\n      ‫وفنيلــة مقلمــة تشــبه بلونهــا فنيلــة نــادي ‪ ....‬وقامــوا بالبحــث عــن أي‬\n      ‫ســيارة لســرقتها ووجــدا ســيارة مــن نــوع ‪ ......‬متوقفــة جــوار أحــد املنــازل‬\n      ‫يف حــي ‪ ....‬فحــاول صديقــه ‪ ............‬فتــح بــاب الســيارة باملفتــاح الــذي‬\n      ‫عثــر عليــه ســابقا لكــن لــم يســتطع ثــم حــاول هــو أن يفتــح الســيارة فلــم‬\n      ‫يســتطع فعــاود صديقــه‪ .....‬احملاولــة وفتــح الســيارة باملفتــاح وقــام‬\n\n\n‫‪215‬‬\n\f‫بتشــغيلها باملفتــاح ذاتــه وقــام هــو بقيــادة الســيارة وذهبــا علــى الســيارة‬\n‫واتصــل علــى صديقــه ‪ ..... /‬وأخبــره أنهــم قامــوا بســرقة ســيارة وأنهــم‬\n‫يريــدون الذهــاب بهــا إلــى اســتراحة يف طريــق املطــار فطلــب منهــم ‪...... /‬‬\n‫الذهــاب معهــم فذهبــوا لــه حيــث كان يجلــس يف حديقــة ‪ ......‬وركــب‬\n‫معهــم وتوجهــوا لالســتراحة الواقعــة يف طريــق املطــار يف ‪ ......‬وقبيــل‬\n‫وصولهــم لالســتراحة قامــوا بإخفــاء الســيارة بــن األشــجار كــي ال‬\n‫يشــاهدها أصدقائهــم ومكثــوا عنــد االســتراحة عــدة دقائــق ثــم عــادوا‬\n‫للســيارة وركبــوا بهــا يريــدون العــودة للحــي وبطريــق العــودة كان يقــود‬\n‫الســيارة ‪ ...... /‬وعنــد وصولهــم لطريــق الدائــري الثانــي علــى طريــق‬\n‫اخلدمــة مــن اجلهــة األخــرى املقابلــة ملجمــع ‪ .....‬التجــاري انحرفــت بهــم‬\n‫الســيارة واصطدمــوا بســيارة مــن نــوع ‪ ....‬كانــت متوقفــة ونزلــوا مــن‬\n‫الســيارة وهربــوا جميع ـ ًا ثــم عــاد ‪ ....... /‬إلــى املوقــع للبحــث عــن جوالــه‬\n‫الــذي فقــده يف الســيارة ومت القبــض عليــه وجــرى االنتقــال مــع املدعــى‬\n‫عليهــم كال علــى حــده وطلــب منهــم اإلرشــاد إلــى موقــع االســتراحة‬\n‫التــي ذهبــوا لهــا بواســطة الســيارة ‪ ......‬املســروقة واملوقــع الــذي يدعــي‬\n‫أنهــم أخفــوا الســيارة بــه وكذلــك اإلرشــاد علــى موقــع احلــادث الــذي‬\n‫وقــع لهــم أثنــاء قيادتهــم تلــك الســيارة املســروقة فأرشــد كال منهــم إلــى‬\n‫اســتراحة يف طريــق املطــار يف ‪ .....‬عبــارة عــن ملعــب كــرة قــدم مــزروع‬\n‫محــاط بســياج حديــدي كمــا أرشــد علــى موقــع علــى بعــد عــدة أمتــار‬\n‫قبيــل االســتراحة يشــبه املوقــف اجلانبــي محــاط باألشــجار وذكــر بأنــه‬\n‫هــو املوقــع الــذي أخفــوا فيــه الســيارة وبالنســبة ملوقــع احلــادث الــذي وقــع‬\n‫لهــم أرشــد علــى موقــع يقــع يف الطريــق الدائــري الثانــي مقابــل مجمــع‬\n‫‪ .......‬التجــاري وقــد انتهــى التحقيــق علــى توجيــه االتهــام إلــى املدعــى‬\n\n\n                                                                                        ‫‪216‬‬\n\f      ‫عليهــم باالشــتراك يف ســرقة ســيارة مــن نــوع ‪ ......‬والتجــول بهــا وإخفائهــا‬\n      ‫والتخطيــط ســويا علــى ذلــك واالصطــدام بســيارة أخــرى كانــت متوقفة‬\n      ‫والهــروب مــن املوقــع وذلــك لألدلــة والقرائــن التاليــة أوال‪ :‬مــا جــاء‬\n      ‫باعتــراف املتهــم ‪ ......‬عليــه شــرعا املــدون علــى صفحــة (‪ )14_11‬مــن‬\n      ‫ملــف التحقيــق رقــم ‪ 3‬ثانيــا‪ :‬مــا جــاء باعتــراف املتهــم ‪......‬عليــه شــرعا‬\n      ‫املــدون علــى صفحــة ‪1‬و ‪ 2‬مــن ملــف التحقيــق رقــم ‪ 4‬ثالثــا‪ :‬مــا جــاء‬\n      ‫باعتــراف املتهــم ‪........‬عليــه شــرعا املــدون علــى صفحــة ‪ 3‬مــن ملــف‬\n      ‫التحقيــق رقــم ‪ 6‬رابعــا‪ :‬مــا جــاء يف محاضــر االســتدالل املدونــة علــى‬\n      ‫صفحــة ‪ 7/6/5‬مــن ملــف التحقيــق رقــم ‪ 6‬خامســا‪ :‬مــا جــاء يف محضــر‬\n      ‫دوريــات األمــن وببحــث ســوابقهم عثــر للثانــي علــى ســابقة ســرقة ولــم‬\n      ‫يعثــر لــأول والثالــث علــى ســوابق مســجله وحيــث إن مــا أقــدم عليــه‬\n      ‫املذكــورون فعــل محــرم ومعاقــب عليــه شــرعا أطلــب إثبــات مــا أســند‬\n      ‫إليهــم واحلكــم بتعزيرهــم علمــا بــأن احلــق اخلــاص انتهــى بالتنــازل وهــم‬\n      ‫ســجناء علــى ذمــة هــذه القضيــة بتاريــخ ‪1433/9/5‬ه ـ وبســؤال املدعــى‬\n      ‫عليهــم عمــا جــاء بدعــوى املدعــى العــام أجابــوا وهــم ينطقــون بالعربيــة‬\n      ‫قائلــن مــا ذكــره املدعــى العــام يف دعــواه صحيــح جملــة وتفصيــا ففــي‬\n      ‫التاريــخ املذكــور يف الدعــوى اتفقنــا جميعــا علــى ســرقة إحــدى‬\n      ‫الســيارات فوجــد أحدنــا مفتــاح ســيارة ملقــى علــى األرض فأخــذه ثــم‬\n      ‫قمنــا مبحاولــة فتــح الســيارة املذكــورة يف الدعــوى فلــم تنفتــح فتناوبنــا‬\n      ‫عليهــا حملاولــة فتحهــا فتــم فتحهــا ألحدنــا وتناوبنــا جميعــا يف قيدتهــا‬\n      ‫وذهبنــا عليهــا ســويا إلــي االســتراحة املذكــورة يف الدعــوى وجــرى‬\n      ‫إخفائهــا بجانــب االســتراحة بــن األشــجار ثــم التقينــا بزمالئنــا يف‬\n      ‫االســتراحة املذكــورة وهــم ال يعلمــون عــن الســيارة ثــم ذهبنــا ســويا علــى‬\n\n\n‫‪217‬‬\n\f‫الســيارة املســروقة ووقــع علينــا حــادث مــروري علــى الطريــق الدائــري‬\n‫بجــوار أســواق ‪ ...‬ب‪......‬حيــث صدمنــا ســيارة نــوع ‪ .....‬وحلــق بالســيارتني‬\n‫تلــف فهربنــا مــن املوقــع بعــد احلــادث كمــا أردف املدعــى عليــه ‪ .....‬قائــا‬\n‫إنــه بعــد وقــوع احلــادث وهروبنــا مــن املوقــع تذكــرت أن جوالــي ســقط‬\n‫داخــل الســيارة فرجعــت ألخــذه عندهــا قبــض علــى رجــال األمــن وقمــت‬\n‫بإرشــادهم علــى املدعــى عليهمــا اآلخريــن فتــم القبــض عليهمــا هكــذا‬\n‫أجابــوا هــذا وبالرجــوع إلــى املعاملــة وجــد بهــا تنــازل صاحــب احلق اخلاص‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــى عليهــم‬\n‫صادقــوا علــى دعــوى املدعــى العــام فأقــروا بســرقة الســيارة املذكــورة‬\n‫يف الدعــوى وذلــك بفتحهــا وكانــت مقفلــة و التنــاوب فيمــا بينهــم‬\n‫بقيادتهــا ووقــوع حــادث مــروري عليهــم بهــا بصدمهــم بســيارة أخــرى و‬\n‫إحلــاق تلــف بالســيارتني والهــروب مــن املوقــع ومبــا أن مــا أقــدم عليــه‬\n‫املدعــى عليهــم اعتــداء بغيــر حــق علــى ملــك اآلخريــن وهــى متقومــة‬\n‫محترمــة ومبــا أن هــذه اجلنايــة ومثيالتهــا فيهــا إخافــة للنــاس علــى‬\n‫أموالهــم وانتهــاك حلرمــة هــذا البلــد املبــارك الــذي حرمــه اهلل وتوعــد‬\n‫بالعقــاب علــى مــن انتهــك محارمــه ومبــا أن التعزيــر يشــرع يف كل‬\n‫معصيــة ال حــد فيهــا وال كفــارة وهــو يختلــف باختــاف األحــوال‬\n‫واألشــخاص والزمــان واملــكان وتقديــر ذلــك راجــع إلــى نظــر احلاكــم‬\n‫مبــا يــراه محققــا للزجــر والــردع جلميــع مــا ذكــر فقــد حكمــت بتعزيــر‬\n‫املدعــى عليهــم وذلــك بجلــد كل واحــد منهــم ثالثمائــة وخمســن جلــدة‬\n‫تقــع علــى بــدن كل واحــد منهــم علــى ســبع دفعــات متســاويات وبــن‬\n‫كل دفعــة وأخــرى عشــرة أيــام ويســجن كل واحــد منهــم تســعة أشــهر‬\n‫كاملــة ابتــداء مــن تاريــخ إيقافهــم ويؤخــذ عليهــم التعهــد بعــدم العــودة‬\n\n\n                                                                                      ‫‪218‬‬\n\f      ‫ملثــل ذلــك وبعــرض احلكــم قــرر املدعــى عليهــم القناعــة بــه وقــرر املدعــي‬\n      ‫العــام عــدم القناعــة باحلكــم وطلــب رفعــه حملكمــة االســتئناف بــدون‬\n      ‫الئحــة اعتراضيــة فأجيــب لطلبــه وأغلقــت اجللســة الســاعة ‪11 : 00‬‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n                                                             ‫حرر يف ‪1433/10/25‬هـ‬\n      ‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم الســبت ‪1433/12/18‬ه ـ‬\n      ‫افتتحــت اجللســة الســاعة الثانيــة عشــر وقــد وردت املعاملــة مــن محكمــة‬\n      ‫االســتئناف مبكــة املكرمــة مــزودة بالقــرار الصــادر مــن أصحــاب‬\n      ‫الفضيلــة قضــاة محكمــة االســتئناف يف الدائــرة اجلزائيــة الرابعــة‬\n      ‫برقــم ‪ 33457136‬وتاريــخ ‪1433/11 /17‬ه ـ املتضمــن بعــد املقدمــة أنــه‬\n      ‫بدراســة احلكــم وصــورة ضبطــه تقــرر إعادتهــا لفضيلــة ناظــر القضيــة‬\n      ‫ملالحظــة أن القاضــي لــم يوضــح أن مــا حكــم بــه لقــاء ثبــوت إدانــة‬\n      ‫املدعــى عليهــم بالســرقة أم للتهمــة وإذا أثبــت الســرقة فهــل هــي مــن‬\n      ‫حــرز فــإن كانــت كذلــك فهــي ليســت مــن اختصاصــه وإن كانــت‬\n      ‫مــن غيــر حــرز فهــي مــن اختصاصــه فيلــزم اإليضــاح يف ذلــك قبــل إيقــاع‬\n      ‫العقوبــة واهلل املوفــق عليــه أجيــب أصحــاب الفضيلــة بــأن املدعــى عليهــم‬\n      ‫أقــروا بســرقة الســيارة املذكــورة يف الدعــوى وهــي واقفــة عنــد أحــد‬\n      ‫املنــازل مبفتــاح كان معهــم وهــذا هــو الــذي جــاء يف ملخــص التحقيــق‬\n      ‫ومــا تضمنتــه الدعــوى العامــة ومــن املعلــوم أن هــذه الســرقة واحلالــة‬\n      ‫هــذه ليســت مــن حــرز والتعزيــر كان لذلــك وقــد نــص العلمــاء علــى‬\n      ‫أن التعزيــر مشــروع يف كل معصيــة ال حــد فيهــا وال كفــارة وأمــا مــا‬\n      ‫ذكــره أصحــاب الفضيلــة مــن إثبــات ذلــك فعليــه أجيــب بــأن تســبيب‬\n      ‫احلكــم يغنــي عــن هــذا فلــو لــم تثبــت جنايتهــم مــا مت تعزيرهــم وقــد‬\n\n\n‫‪219‬‬\n\f‫نصيــت علــى احلكــم وهــو أقــوى صيغــة يف األحــكام وهــو يغنــي عــن‬\n‫غيــره مــن األلفــاظ وال مشــاحة يف االصطالحــات وعلــى هــذا فإننــي‬\n‫علــى حكمــي الســابق وقــد انتهــت اجللســة يف متــام الســاعة الثانيــة عشــر‬\n‫والربــع وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه‬\n                                            ‫وســلم حــرر يف ‪1433/12/18‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ففــي يــوم الســبت املوافــق‪ 1434/02/02‬ه ـ‬\n‫افتتحــت اجللســة الســاعة ‪ 09 : 00‬حيــث عــادت املعاملــة مــن محكمــة‬\n‫االســتئناف مــن مكــة املكرمــة مــزودة بالقــرار الصــادر مــن أصحــاب‬\n‫الفضيلــة قضــاة االســتئناف بالدائــرة اجلزائيــة الرابعــة برقــم ‪3410497‬‬\n‫يف ‪1434/1/12‬ه ـ واملتضمــن بعــد املقدمــة أنــه بدراســة القــرار وصــورة‬\n‫ضبطــه تقــرر إعادتهــا إلــى فضيلــة حاكمهــا ملالحظــة أن مــا أجــاب بــه‬\n‫فضيلتــه علــى قرارنــا رقــم ‪ 33457136‬وتاريــخ ‪1433/11/17‬ه ـ غيــر‬\n‫مــاق وعليــه التمشــي مبــا جــاء بــه القــرار وبــاهلل التوفيــق وعليــه أجيــب‬\n‫أصحــاب الفضيلــة بــأن املدعــى عليهــم قــد أقــروا بســرقة الســيارة‬\n‫املبينــة يف الدعــوى وهــي ليســت مــن حــرز وتعزيرهــم كان ألجــل ثبــوت‬\n‫هــذه اجلنايــة وقــد نــص العلمــاء علــى أن التعزيــر يشــرع يف كل معصيــة‬\n‫الحــد فيهــا وال كفــارة جــاء يف كشــاف القنــاع ج‪ 14‬ص‪ 49‬لإلمــام‬\n‫البهوتــي رحمــه اهلل بعــد أن ســاق جملــة مــن موجبــات التعزيــر قــال مــا‬\n‫نصــه (وكســرقة مــا ال قطــع فيــه) والتعزيــر مــن اختصــاص احملاكــم‬\n‫اجلزائيــة وعلــى هــذا فإنــي علــى حكمــي الســابق وقــد انتهــت اجللســة يف‬\n‫متــام الســاعة ‪ 10:9‬وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                              ‫آلــه وصحبــه وســلم حــرر يف ‪1434/02/02‬ه ـ‬\n‫احلمــد هلل والصــاة والســام علــى رســول اهلل وبعــد ‪ ...‬نحــن رئيــس‬\n\n\n                                                                                     ‫‪220‬‬\n\f      ‫وقضــاة الدائــرة اجلزائيــة الرابعــة يف محكمــة االســتئناف مبنطقة مكة‬\n      ‫املكرمــة جــرى منــا االطــاع علــى القــرار رقــم ‪ 33438692‬وتاريــخ‬\n      ‫‪1433/10/25‬ه ـ الصــادر مــن فضيلــة الشــيخ‪ ......‬القاضــي باحملكمــة‬\n      ‫اجلزائيــة باملدينــة املنــورة‪ ،‬املتضمــن دعــوى املدعــي العــام ضــد‪.......‬‬\n      ‫تشــادي اجلنســية ورفقــاه املتهمــن يف ســرقة ســيارة‪ ،‬احملكــوم فيــه مبــا‬\n      ‫دون باطنــه املالحــظ عليــه بقــرار‪ 3410497‬وتاريــخ ‪1434/1/12‬هــ‪.‬‬\n      ‫وبدراســة القــرار وصــورة ضبطــه تقــررت املوافقــة علــى احلكــم بعــد‬\n      ‫اإليضــاح األخيــر‪ ،‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                                                    ‫وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪221‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":211,"source_page_end":221,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"5d8705750ae9a671eeb66a5d00ad3478525fa6cb49e50a1fff250a316fb96b4f","normalized_text_hash":"f04fec145a77cb62180d432e82747612d6e01396bb2c2d3df2cf858a1e0d9813","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p211-33438692"},{"id":"a9ecec91-24b9-507c-bb56-6ec9cd38481b","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة سيارة -تسبب يف سرقة -إهمال وتفريط -شبهة سرقة -تعزير بالسجن واإلبعاد عن الباد.","document_number":"3435727","case_number":"33619160","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف مبكة املكرمة بالقرار","circuit":"الدائرة اجلزائية الثالثة وهم كال من الشيخ ........والشيخ ..........","issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/11","year":"1434","subject":"سرقة -سرقة سيارة -تسبب يف سرقة -إهمال وتفريط -شبهة سرقة -تعزير بالسجن واإلبعاد عن الباد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك ‪ 3435727 :‬تاريخه ‪1434/02/11 :‬هـ‬\n                    ‫رقم الدعوى ‪33619160:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n          ‫‪ 34246460‬تاريخه ‪1434/06/20 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬ســرقة ســيارة ‪ -‬تســبب يف ســرقة ‪ -‬إهمــال وتفريــط ‪ -‬شــبهة‬\n                       ‫ســرقة ‪ -‬تعزيــر بالســجن واإلبعــاد عــن البــاد‪.‬‬\n\n\n\n\n‫‪ -‬قــول اهلل تعالــى ( وتعاونــوا علــى البــر والتقــوى و ال تعانــوا علــى اإلثــم‬\n                                                                       ‫والعدوان)‪.‬‬\n‫‪ -‬قولــه صلــى اهلل عليــه وســلم (كل املســلم علــى املســلم حــرام دمــه‬\n                                                               ‫ومالــه وعرضــه )‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى العامــة ضــد املدعــى عليهمــا يحمــان بطاقــة بديلــة‬\n‫وطلــب إثبــات إدانتهمــا باســتالم ســيارة مــن شــخص مــع مفتاحهــا أثنــاء‬\n‫عملهــا يف مغســلة ســيارات لغــرض غســلها وتركهــا أمــام املغســلة ممــا‬\n‫تســبب يف ســرقتها منهمــا أو مــن غيرهمــا وطلــب املدعــي العــام إثبــات مــا‬\n‫أســند إليهمــا واحلكــم عليهمــا بعقوبــة تعزيريــة ‪ -‬قبــض علــى املدعــى‬\n‫عليهمــا بعــد بــاغ مــن أحــد األشــخاص أنــه ســلم ســيارته لهمــا مبغســلة‬\n‫الســيارات التــي يعمــان بهــا وعنــد رجوعــه الســتالمها لــم يجــد الســيارة‬\n‫يف مكانهــا واتهــم املدعــى عليهمــا بســرقتها ‪ ،‬وأنكــر املدعــى عليهمــا‬\n‫الســرقة ونظــر ًا إلقــرار املدعــى عليهمــا باســتالم الســيارة ومفتاحهــا‬\n\n                                                                                       ‫‪222‬‬\n\f      ‫وبقيــت الســيارة مــدة طويلــة باملغســلة ممــا جعــل مفتاحهــا عرضــة‬\n      ‫للضيــاع لــذا فقــد ثبــت إدانــة املدعــى عليهمــا باســتالم الســيارة مــع‬\n      ‫مفتاحهــا أثنــاء عملهــا باملغســلة لغــرض غســلها باإلهمــال والتفريــط يف‬\n      ‫الســيارة ممــا تســبب يف ســرقتها والشــبهة بحقهمــا بســرقتها وحكمــت‬\n      ‫احملكمــة بالســجن واإلبعــاد عــن البــاد ‪ ،‬مت تصديــق احلكــم مــن‬\n      ‫محكمــة االســتئناف مبكــة املكرمــة بالقــرار رقــم ‪ 3424646‬يف‬\n                                                                 ‫‪1434/6/20‬هــ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪..........‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n      ‫احملكمــة اجلزائيــة يف محافظــة جدة‪/‬املســاعد برقــم‪ .......‬وتاريــخ‬\n      ‫‪ 1433/10/23‬هـ املقيدة باحملكمة برقم ‪ .......‬وتاريخ ‪1433/10/17‬‬\n      ‫ه ـ ففــي يــوم االثنــن املوافــق‪ 1433/11/08‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 01 : 00‬وفيهــا حضــر املدعــي العــام ‪ ......‬املكلــف باالدعــاء العــام‬\n      ‫مبوجــب خطــاب هيئــة التحقيــق واالدعــاء العــام رقــم ‪ .....‬وتاريــخ‬\n      ‫‪1433/3/6‬ه ـ وأدعــى قائــا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة االدعــاء‬\n      ‫العــام مبحافظــة جــدة أدعــي علــى ‪ 28، .......‬عامـ ًا املهنــة عامــل صومالــي‬\n      ‫اجلنســية مبوجــب البطاقــة البديلــة رقــم (‪ ).........‬موقــوف بســجون جــدة‬\n      ‫مبوجــب امــر متديــد رقــم ‪ .........‬وتاريــخ ‪1432/12/11‬ه ـ علــى ‪25 3333‬‬\n      ‫عامـ ًا املهنــة عامــل صومالــي اجلنســية مبوجب البطاقــة البديلة رقم (‪)......‬‬\n      ‫موقــوف بســجون جــدة بأمــر متديــد رقــم ‪ ......‬وتاريــخ ‪1432/12/11‬ه ـ‬\n      ‫بتاريــخ ‪1432/11/26‬ه ـ ابلــغ مركــز شــرطة اجلنوبيــة املواطــن‪......../‬‬\n\n‫‪223‬‬\n\f‫عــن ســرقة ســيارته مــن نــوع رقــم اللوحــة (‪ ).......‬لــون بعــد إحضارهــا‬\n‫إلــى مغســلة ســيارات بحــي مــن قبــل مكفولــه املدعــو‪ .......‬باكســتاني‬\n‫اجلنســية لغــرض غســلها وقــام بتســليم مفتاحهــا إلــى املدعــى عليــه الثانــي‬\n‫الــذي بــدوره ســلم املفتــاح للمدعــى عليــه األول وعنــد رجوعــه الســتالمها‬\n‫مت إبالغــه مــن قبــل املذكوريــن عــن عــدم عثورهــم علــى مفتــاح الســيارة‬\n‫وعنــد قيامــه بإحضــار املفتــاح االحتياطــي لــم يجــد الســيارة يف مكانهــا‬\n‫ويتهــم املدعــى عليهمــا بســرقتها وباســتجواب املدعــى عليــه‪ ......‬افــاد‬\n‫بانــه منــذ عشــرين يوم ـ ًا قــام مكفــول مالــك الســيارة املدعــو‪......‬‬\n‫بإحضــار ســيارة مــن نــوع وبهــا عطــل باملاكينــة وطلــب منــه غســلها‬\n‫يف املغســلة التــي يعمــل بهــا وهــي مقفلــة بعــد ان قــام باســتالم مفتــاح‬\n‫الســيارة وتركهــا منــذ ذلــك احلــن ولــم يرجــع الســتالمها وقــام بإبــاغ‬\n‫مالــك الســيارة عــن فقــده مفتــاح الســيارة بعــد ان قــام بتســليمه للثانــي‬\n‫وبعــد عــدة أيــام فوجــى بعــدم وجــود الســيارة وظــن ان مالكهــا حضــر‬\n‫الســتالمها وفوجــئ بعــد ذلــك برجــال البحــث اجلنائــي باحلضــور والقبــض‬\n‫عليــه وباســتجواب املدعــى عليــه‪ .....‬تطابقــت أقوالــه مــع مــا جــاء يف‬\n‫أقــوال املدعــى عليــه األول وانتهــى التحقيــق إلــى توجيــه االتهــام للمدعــى‬\n‫عليهمــا (‪ ..... )2( ...... )1‬باســتالم ســيارة املواطــن‪ .........../‬مــع مفتاحهــا‬\n‫أثنــاء عملهمــا مبغســلة بحــي لغــرض غســلها ومــن ثــم تركهــا أمــام‬\n‫املغســلة ممــا تســبب يف ســرقتها منهمــا او مــن غيرهمــا وذلــك لألدلــة‬\n‫والقرائــن التاليــة مــا جــاء بدعــوى املدعــي مالــك الســيارة عــن ســرقة‬\n‫ســيارته بعــد تســليمها للمذكوريــن مــع املفتــاح اخلــاص بهــا لفــه (‪ )8‬مــا‬\n‫جــاء بأقوالهمــا اســتالم الســيارة مــع مفتاحهــا ومــن ثــم ادعائهمــا بفقــدان‬\n‫مفتــاح الســيارة لفــه رقــم ‪ 8‬ص ‪11-1‬وبالبحــث عــن ســوابقهما لــم يعثــر‬\n\n\n                                                                                       ‫‪224‬‬\n\f      ‫لهمــا علــى ســوابق مســجلة وحيــث ان مــا أقــدم عليــه املدعــى عليهمــا‬\n      ‫فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا اطلــب إثبــات مــا اســند إليهمــا‬\n      ‫وتعزيرهمــا لقــاء ذلــك (علمـ ًا بــان احلــق اخلــاص ال زال قائمـاً) وبعــرض مــا‬\n      ‫ورد بدعــوى املدعــي العــام علــى املدعــى عليهمــا احلاضريــن يف املجلــس‬\n      ‫ا مــا ورد يف دعــوى‬     ‫الشــرعي قــرر كل واحــد منهمــا علــى انفــراد قائ ـ ً‬\n      ‫املدعــي العــام مــن توجيــه االتهــام لــي لنــا باســتالم ســيارة املواطــن‪..........‬‬\n      ‫مــع مفتاحهــا أثنــاء عملنــا مبغســلة بحــي لغــرض غســلها ومــن ثــم تركها‬\n      ‫أمــام املغســلة ممــا تســبب يف ســرقتها منــا او مــن غيرنــا علــى الصفــة‬\n      ‫املتقدمــة يف الدعــوى فغيــر صحيــح والصحيــح أن الســيارة املشــار إليهــا‬\n      ‫قــد أحضرهــا إلينــا شــخص باكســتاني اجلنســية وتعطلــت عنــد وصولهــا‬\n      ‫للمغســلة وتركهــا وكان املفتــاح بحوزتنــا وفقــد منــا املفتــاح فحضــر‬\n      ‫إلينــا الشــخص الباكســتاني وطلــب أن نتحمــل تكلفــة املفتــاح فوافقنــا‬\n      ‫علــى ذلــك فوجدنــا مفتــاح قمنــا بتجربتــه علــى الســيارة فقــام بفتــح‬\n      ‫الســيارة ولــم يقــم بتشــغيلها فقــال بــأن املفتــاح يحتــاج إلــى برمجــه فقلنــا‬\n      ‫لــه بأنــا مســتعدين بتحمــل تكلفــة البرمجــة فأخــذ املفتــاح معــه ألجــل‬\n      ‫أن يقــوم بالبرمجــة ولــم يعــد بعــد ذلــك هــذا جوابــي علــى الدعــوى عليــه‬\n      ‫فقــد جــرى ســؤال املدعــي العــام هــل لديــه بينــه علــى مــا ذكــر قــال نعــم‬\n      ‫وبينتــي تتمثــل يف مــا جــاء بدعــوى املدعــي مالــك الســيارة عــن ســرقة‬\n      ‫ســيارته بعــد تســليمها للمذكوريــن مــع املفتــاح اخلــاص بهــا لفــه (‪ )8‬مــا‬\n      ‫جــاء بأقوالهمــا اســتالم الســيارة مــع مفتاحهــا ومــن ثــم ادعائهمــا بفقــدان‬\n      ‫مفتــاح الســيارة لفــه رقــم ‪ 8‬ص ‪ 11-1‬عليــه فقــد جــرى ســؤاله هــل لديــة‬\n      ‫زيــادة بينــه قــال ال يوجــد لــدي ســوى مــا قدمــت فبنــاء علــى مــا تقــدم مــن‬\n      ‫الدعــوى واإلجابــة وإقــرار املدعــى عليهمــا باســتالم الســيارة ومفتاحهــا‬\n\n\n‫‪225‬‬\n\f‫وحيــث ان الســيارة قــد بقيــت مــده طويلــه يف املغســلة كمــا ورد يف‬\n‫أقــوال املدعــي يف محضــر التحقيــق املرفــق باملعاملــة علــى اللفــة (‪)8‬و(‪)9‬‬\n‫ممــا يجعــل مفتاحهــا عرضــة للضيــاع ولقولــه تعالــى { وتعاونــوا علــى‬\n‫البــر والتقــوى وال تعاونــوا علــى اإلثــم والعــدوان } وملــا يف فعــل املدعــى‬\n‫عليــه مــن عصيــان هلل ولرســوله ولولــي األمــر ولقولــه صلــى اهلل عليــه‬\n‫وســلم (كل املســلم علــى املســلم حــرام دمــه ومالــه وعرضــه ) وجلميــع مــا‬\n‫تقــدم فقــد ثبــت لــدي إدانــة املدعــى عليهمــا ‪ ............‬و ‪ ............‬باســتالم‬\n‫ســيارة املواطــن‪ ...........‬مــع مفتاحهــا أثنــاء عملهمــا مبغســلة بحــي لغــرض‬\n‫غســلها باإلهمــال والتفريــط يف الســيارة ممــا تســبب يف ســرقتها ووجــود‬\n‫الشــبهة يف حقهمــا بســرقة الســيارة املذكــورة وحكمــت عليهمــا لقــاء‬\n‫ذلــك مبــا يلــي أو ًال ســجن كل واحــد منهمــا ملــده عشــرة أشــهر حتســب‬\n‫منهــا مــده إيقافــه علــى ذمــة هــذه القضيــة وإبعادهمــا عــن البــاد بعــد‬\n‫تنفيــذ محكوميتهمــا وعــدم الســماح لهمــا بالعــودة إليهــا مــرة أخــرى‬\n‫وبعرضــه علــى الطرفــن قــرر املدعــى عليهمــا القناعــة وقــرر املدعــي‬\n‫العــام عــدم القناعــة وطلــب االســتئناف فأجبتــه لطلبــه وســيجري اتخــاذ‬\n‫الــازم حســب التعليمــات جــرى النطــق باحلكــم يف متام الســاعة الواحدة‬\n‫والربــع ظهــرا وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم حــرر يف ‪ 1433/11/08‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم االثنــن املوافــق ‪1434/7/10‬ه ـ الســاعة‬\n‫الثامنــة وخمــس وأربعــون دقيقــة فتحــت اجللســة لــدي انــا ‪...........‬‬\n‫القاضــي باحملكمــة اجلزائيــة مبحافظــة جــده والقائــم بعمــل القاضــي‬\n‫‪ .........‬مبوجــب خطــاب التكليــف رقــم ‪.............‬يف ‪1434/7/8‬ه ـ‬\n‫وجــرى االطــاع علــى أوراق املعاملــة وكانــت قــد عــادت املعاملــة مــن‬\n\n\n                                                                                           ‫‪226‬‬\n\f      ‫محكمــة االســتئناف مبكــة املكرمــة وبرفقهــا قرارهــا رقــم ‪........‬يف‬\n      ‫‪1434/6/20‬ه ـ باملصادقــة علــى احلكــم ونــص احلاجــة منــه (وبدراســة‬\n      ‫القــرار وصــورة ضبطــه والئحتــه االعتراضيــة تقــرر املوافقــة علــى‬\n      ‫احلكــم واهلل املوفــق )وموقــع ومختــوم مــن اصحــاب الفضيلــة أعضــاء‬\n      ‫الدائــرة اجلزائيــة الثالثــة وهــم كال مــن الشــيخ ‪ ........‬والشــيخ ‪..........‬‬\n      ‫والشــيخ‪ ..............‬فجــرى تدوينــه حفظــا للواقــع وجــرى قفلهــا يف متــام‬\n      ‫الســاعة التاســعة وصلــى اهلل علــى نبينــا محمــد والــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪227‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":222,"source_page_end":227,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"97a7b480fa5de43490ed04e948744cfce2bf423facba163b1379f758d710a1b1","normalized_text_hash":"612521e219e3eb0d44a44995b6ce1ba2a385303fd8fa1a5c9f4c1941d8fed8d9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p222-3435727"},{"id":"568131e7-0e1c-54e8-a7c2-796d489723a8","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -اختاس -خيانة أمانة -استغالل موظف عمله يف مصرف لالختاس والسرقة -تضمن املثل يف احلق اخلاص -سماع دعوى احلق اخلاص مع احلق العام -عدم قبول رجوع املقر عن إقراره يف احلق اخلاص -األصل تضمن املختلس الربح الفائت باختالسه -توافق داللة ظاهر احلال مع أصل االختيار والرضى يف أقوال املكلف -حكم بتسليم مبلغ للمدعى اخلاص -ثبوت إدانة -تعزير بالسجن واجللد يف مكان عام -أسباب تشديد العقوبة -ثبوت إدانة","document_number":"3447287","case_number":"33656547","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/2/25","year":"1434","subject":"سرقة -اختاس -خيانة أمانة -استغالل موظف عمله يف مصرف لالختاس والسرقة -تضمن املثل يف احلق اخلاص -سماع دعوى احلق اخلاص مع احلق العام -عدم قبول رجوع املقر عن إقراره يف احلق اخلاص -األصل تضمن املختلس الربح الفائت باختالسه -توافق داللة ظاهر احلال مع أصل االختيار والرضى يف أقوال املكلف -حكم بتسليم مبلغ للمدعى اخلاص -ثبوت إدانة -تعزير بالسجن واجللد يف مكان عام -أسباب تشديد العقوبة -ثبوت إدانة","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"  ‫رقم الصك ‪ 3447287 :‬تاريخه‪1434/2/25 :‬هـ‬\n                     ‫رقم الدعوى‪33656547:‬‬\n      ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 35119440‬تاريخه‪1435/1/17 :‬هـ‬\n\n\n\n‫ســرقة ‪ -‬اختــاس ‪ -‬خيانــة أمانــة ‪ -‬اســتغالل موظــف عملــه يف مصــرف‬\n‫لالختــاس والســرقة ‪ -‬تضمــن املثــل يف احلــق اخلــاص ‪ -‬ســماع دعــوى‬\n‫احلــق اخلــاص مــع احلــق العــام ‪ -‬عــدم قبــول رجــوع املقــر عــن إقــراره يف‬\n‫احلــق اخلــاص ‪ -‬األصــل تضمــن املختلــس الربــح الفائــت باختالســه‬\n‫‪ -‬توافــق داللــة ظاهــر احلــال مــع أصــل االختيــار والرضــى يف أقــوال‬\n‫املكلــف ‪ -‬حكــم بتســليم مبلــغ للمدعــى اخلــاص ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر‬\n‫بالســجن واجللــد يف مــكان عــام ‪ -‬أســباب تشــديد العقوبــة ‪ -‬ثبــوت إدانــة‬\n‫مصــرف باإلهمــال مبراقبــة حســابات العمــاء بشــكل دوري ممــا تســبب‬\n‫يف حتويــات غيــر شــرعية وغيــر نظاميــة وتوجيــه اللــوم للمصــرف‬\n                           ‫بســبب ذلــك ‪ -‬عــدم ثبــوت إدانــة ‪ -‬صــرف نظــر ‪.‬‬\n\n\n\n\n‫أن األصــل يف الضمــان ضمــان املثــل كمــا هــو مــروي عــن اإلمــام مالــك‬\n‫و الشــافعي وهــو روايــة عــن اإلمــام أحمــد اختارهــا شــيخ اإلســام و ابــن‬\n‫القيــم و الشــيخ محمــد بــن إبراهيــم و قضــى بــه شــريح و أفتــى بــه‬\n‫الزهــري ‪ .‬ينظــر ‪ :‬املنتقــى للباجــي (‪ )272/5‬و فتــح البــاري ( ‪)150/5‬‬\n‫و املغنــي ( ‪ )361/7‬و الفــروع ( ‪ )507/4‬مجمــوع فتــاوى شــيخ اإلســام‬\n‫(‪ )563/20‬إعــام املوقعــن (‪ )324-322/1‬احمللــى ( ‪ )438/6‬حاشــية‬\n                                                   ‫الــروض املربــع ( ‪.)406/5‬‬\n\n                                                                                    ‫‪228‬‬\n\f      ‫اتهــام املدعــي العــام للمدعــى عليهــم األول والثانــي باســتغالل وظيفتهمــا‬\n      ‫لــدى مصــرف ‪ ....‬وقيامهمــا باختــاس مبلــغ مالــي مــن حســاب عميــل‬\n      ‫دون علمــه أو علــم إدارة املصــرف وذلــك بعــد التخطيــط والتنســيق‬\n      ‫املســبق بينهمــا وقيــام الثانــي بســرقة األرقــام الســرية لبعــض موظفــي‬\n      ‫البنــك ومراقبــي الفــروع إلجنــاز تلــك التحاويــل الغيــر مشــروعة للحســاب‬\n      ‫الشــخصي لزميلــه األول واتهــام الثالــث والرابــع واخلامــس والســادس‬\n      ‫بإعطــاء حريــة التصــرف لــأول بحســاباتهم الشــخصية ممــا ســهل عليــه‬\n      ‫عمليــة اختــاس تلــك األمــوال مــن حســاب العميــل دون علمــه واتهــام‬\n      ‫إدارة مصــرف ‪ ....‬باإلهمــال مبراقبــة حســابات العمــاء بشــكل دوري‬\n      ‫ممــا تســبب ذلــك بإجــراء عــدة عمليــات حتاويــل مــن حســاب العميــل‬\n      ‫لديهــم إلــى حســابات أخــرى دون اكتشــاف ذلــك إال بعــد وقــت متأخــر‬\n      ‫يطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة ‪ ،‬حيــث‬\n      ‫إنــه بتاريــخ ‪1431/1/4‬ه ـ ورد ملركــز شــرطة ‪ ....‬تقريــر دوريــات األمــن‬\n      ‫مبنطقــة الريــاض رقــم (‪ )1005‬املتضمــن القبــض علــى األول والثانــي‬\n      ‫وذلــك بنــاء علــى بــاغ الوكيــل الشــرعي لشــركة ‪ ....‬املصرفيــة ‪...‬‬\n      ‫لقيامهمــا باالتفــاق واالشــتراك ســويا باختــاس مبلــغ مالــي مــن البنــك‬\n      ‫مقــداره (‪ )17.306.602.70‬ســبعة عشــر مليونـ ًا وثالثمائــة وســتة آالف‬\n      ‫وســتمائة وريــاالن وســبعون هللــة مــن حســاب العميــل لديهــم ‪ ...‬وذلــك بعد‬\n      ‫قيــام األول بإنشــاء اشــتراك انترنــت حملفظــة العميــل دون علمــه ومــن ثــم‬\n      ‫الطلــب مــن زميلــه بتنفيــذه عــدة عمليــات بيــع ألســهم العميــل بحجــة أن‬\n      ‫العميــل طلــب منــه ذلــك مــع وعــده لهــم بإحضــاره مســتند أمــر بيــع موقــع‬\n\n‫‪229‬‬\n\f‫مــن العميــل وبعــد أن يتــم بيــع األســهم يطلــب منهــم حتويــل مبالــغ البيــع‬\n‫إلــى حســاب العميــل اجلــاري املربــوط علــى احملفظــة ومــن ثــم يأتــي دور‬\n‫شــريكه الثانــي إجــراء عمليــات حتويــل مــن حســاب العميــل حلســاب‬\n‫األول وحلســاب عمــاء آخريــن أقربــاء لــأول متهيــدا لســحبها منهــم‬\n‫وتســليمها لــأول وكذلــك قيــام الثانــي بســرقة األرقــام الســرية لزمالئــه‬\n‫الصرافــن ســواء الــذي يعملــون معــه بنفــس الفــرع بحــي ‪ ......‬أو بالفــروع‬\n‫األخــرى وكذلــك ســرقة األرقــام الســرية ملراقبــي الفــروع حتــى يتمكــن‬\n‫مــن تنفيــذ تلــك احلــواالت الغيــر مشــروعة ‪ ،‬أقــر املدعــى عليــه األول مبــا‬\n‫جــاء يف الدعــوى ‪ ،‬أقــر املدعــى عليــه الثانــي بتحويــل املبالــغ وأنكــر‬\n‫ســرقة األرقــام الســرية ملوظفــي البنــك ويطلــب وكيلــه تبــرأة موكلــه‬\n‫مــن الدعــوى‪ ،‬أقــر املدعــى عليــه الثالــث بدخــول مبالــغ يف حســابه عــن‬\n‫طريــق املدعــى عليــه األول وأنكــر علمــه بالتفاصيــل وأعادهــا حلســاب‬\n‫األول‪،‬أقــر املدعــى عليــه الرابــع مبــا جــاء يف جــواب الثالــث‪ ،‬أقــر املدعى‬\n‫عليــه اخلامــس مبــا جــاء يف جــواب الثالــث والرابــع ‪ ،‬أقــر املدعــى عليــه‬\n‫الســادس مبــا جــاء يف جــواب الســابقني وأنــه هــو الــذي قــام بتبليــغ ابــن‬\n‫الشــخص املختلــس منــه موضــوع االختــاس وأحضــر بينــة علــى ذلــك‪،‬‬\n‫دليــل املدعــي العــام علــى نفــي املدعــى عليــه الثانــي ســرقة األرقــام‬\n‫الســرية للعمــاء إقــراره بذلــك ودفــع املدعــى عليــه بأنــه اعتــرف تغريــرا‬\n‫مــن محقــق املصــرف ‪ ،‬حضــر املدعــي يف احلــق اخلــاص عــن شــركة ‪....‬‬\n‫وادعــى ضــد املدعــى عليهــم جميعــا بــأن الشــركة املصرفيــة موكلتــه‬\n‫قامــت بشــراء أســهم بعــدد األســهم املســروقة ونوعهــا وتســليمها حملفظــة‬\n‫املختلــس منــه ونتــج عــن ذلــك دفــع موكلتــي مبلــغ خمســة و عشــرين‬\n‫مليونـ ًا و ســتمائة وخمســة وثالثــن ألــف وســبعمائة وســتة و أربعــن ريــا ًال‬\n\n\n                                                                                     ‫‪230‬‬\n\f      ‫وخمــس و خمســن هللــة‪ ،‬اســتعد املدعــى عليــه األول بتحمــل املبلــغ‬\n      ‫كامــا وبــرأ البقيــة مــن املبلــغ ‪،‬أنكــر البقيــة أنهــم أخــذوا شــيئا مــن‬\n      ‫األمــوال احملولــة حلســاباتهم‪،‬فبناء علــى مــا تقــدم وإلقــرار املدعــى عليــه‬\n      ‫األول وإقــرار املدعــى عليــه الثانــي بالتحويــل ولعــدم قبــول رجوعــه عــن‬\n      ‫إقــراره يف ســرقة األرقــام الســرية وخليانــة األمانــة ولكبــر املبالــغ ‪ ،‬ثبوت‬\n      ‫إدانــة املدعــى عليــه األول والثانــي باســتغالل وظيفتهمــا واالشــتراك‬\n      ‫يف اختــاس مبلــغ مالــي مــن حســاب عميــل دون علمــه أو علــم إدارة‬\n      ‫ـرية لبعــض‬ ‫املصــرف و إدانــة املدعــى عليــه ‪ ...‬باســتخدام األرقــام السـ ّ‬\n      ‫موظفــي املصــرف دون إذنهــم أو علمهــم إلجــراء حتويــات غيــر شــرعية‬\n      ‫و ال نظاميــة و إدانــة املصــرف باإلهمــال مبراقبــة حســابات العمــاء‬\n      ‫بشــكل دوري ممــا تســبب بإجــراء عــدة حتويــات مــن حســاب العميــل‬\n      ‫لديهــم إلــى حســابات أخــرى دون اكتشــاف لذلــك إ ّال بعــد وقــت متأخــر‬\n      ‫و لــم يثبــت لــدي إدانــة املدعــى عليهــم البقيــة بإعطائهــم حريــة التصــرف‬\n                                               ‫للمدعــى عليــه ‪ ....‬احلكــم مبــا يلــي ‪:‬‬\n                                                                    ‫أ‪ /‬يف احلق العام ‪:‬‬\n      ‫‪ - 1‬ســجن املدعــى عليــه األول ثمــان ســنوات و جلــده ثمامنائــة جلــدة‬\n      ‫مفرقــة علــى عشــر دفعــات كل دفعــة ثمانــون جلــدة يف مــكان عــام‪.‬‬\n      ‫‪ -2‬ســجن املدعــى عليــه الثانــي ثــاث ســنوات و جلــده مائتــي جلــدة‬\n      ‫مفرقــة علــى أربــع دفعــات كل دفعــة خمســون جلــدة يف مــكان عــام ‪.‬‬\n                                                 ‫‪ -3‬توجيه اللوم الشديد للمصرف ‪.‬‬\n                                                        ‫‪ -4‬براءة باقي املدعى عليهم‪.‬‬\n                                                                 ‫ب‪ /‬يف احلق اخلاص ‪:‬‬\n      ‫‪ -1‬إلــزام املدعــى عليــه األول بتســليم املدعــي اخلــاص املصــرف ثالثمائــة‬\n\n\n‫‪231‬‬\n\f‫واثنــن و ثالثــن ألــف و مائــة و أربعــة و ثمانــن ســهم ًا مــن أســهم املصــرف‬\n‫ودفــع ســبعمائة ريــال أجــرة إنشــاء احملفظــة و دفــع أربعمائــة و ثمانيــة و‬\n‫عشــرين ألــف و تســعمائة و ثمانيــة و ثالثــن ريــا ًال و واحــد و ســتني هللــة‬\n                      ‫باقــي األربــاح بعــد خصــم املبلــغ املوجــود يف احلســاب ‪.‬‬\n‫‪ -2‬صــرف النظــر عــن عمــا عــدا ذلــك ممــا ورد يف دعــوى املدعــي‬\n‫اخلــاص ووكيــل املدعــى عليــه ‪ ..‬الثانــي و أفهمــت وكيــل املدعــي اخلــاص‬\n‫للمصــرف بــأن لــه أخــذ أميــان املدعــى عليهــم عــدا األول علــى نفــي أخــذ‬\n‫شــيء مــن املبالــغ الناجتــة عــن االختــاس محــل الدعــوى متــى مــا أراد ‪.‬‬\n‫قــرر املدعــي العــام االعتــراض بــدون الئحــة وقــرر املدعــي يف احلــق‬\n‫اخلــاص واملدعــى عليهمــا األول والثانــي االعتــراض بالئحــة وقــرر البقيــة‬\n                    ‫القناعــة‪ ،‬تصديــق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                      ‫‪232‬‬\n\f      ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n      ‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n      ‫اجلزائيــة بالريــاض برقــم ‪ 33656547‬وتاريــخ ‪ 1433/11/15‬ه ـ املقيــدة‬\n      ‫باحملكمــة برقــم ‪ 332029054‬وتاريــخ ‪ 1433/11/15‬ه ـ ففــي يــوم‬\n      ‫الثالثــاء املوافــق‪1434/01/ 20‬ه ـ قــدم املدعــي العــام ‪ ....‬الئحــة دعــوى‬\n      ‫عامــة ضــد ‪ ، .... -1 /‬البالــغ مــن العمــر ‪ 30‬عام ـ ًا ‪ ،‬ســعودي اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم (‪)....‬أوقــف بتاريــخ ‪1431/1/4‬ه ـ وأحيــل‬\n      ‫للســجن العــام مبوجــب مذكــرة التوقيــف رقــم (‪ )17/6/1/19‬وتاريــخ‬\n                                                                     ‫‪1431/1/24‬هـ‬\n      ‫‪ ، ....... -2‬البالــغ مــن العمــر ‪ 25‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب‬\n      ‫الســجل املدنــي رقــم (‪)....‬أوقــف بتاريــخ ‪1431/1/4‬ه ـ وأحيــل للســجن‬\n      ‫العــام مبوجــب مذكــرة التوقيــف رقــم (‪ )17/6/1/19‬وتاريــخ‬\n                                                                   ‫‪1431/1/24‬ه ـ‬\n                   ‫‪ .... -3‬مبوجب السجل املدني رقم (‪ )....‬مفرج عنه بالكفالة‪.‬‬\n                ‫‪ ...... -4‬مبوجب السجل املدني رقم (‪ )......‬مفرج عنه بالكفالة‪.‬‬\n                  ‫‪ ..... -5‬مبوجب السجل املدني رقم (‪ ).....‬مفرج عنه بالكفالة‪.‬‬\n                    ‫‪ .... -6‬مبوجب السجل املدني رقم (‪ )....‬مفرج عنه بالكفالة‪.‬‬\n      ‫حيــث إنــه بتاريــخ ‪1431/1/4‬ه ـ ورد ملركــز شــرطة ‪ .....‬تقريــر دوريــات‬\n      ‫األمــن مبنطقــة ‪ ....‬رقــم (‪ )1005‬املتضمــن القبــض علــى األول والثانــي‬\n      ‫وذلــك بنــاء علــى بــاغ الوكيــل الشــرعي لشــركة ‪ ...‬املصرفيــة ‪... /‬‬\n      ‫لقيامهمــا باالتفــاق واالشــتراك ســويا باختــاس مبلــغ مالــي مــن البنــك‬\n\n‫‪233‬‬\n\f‫قــدره (‪ )17.306.602.70‬ســبعة عشــر مليون ـ ًا وثالثمائــة وســتة آالف‬\n‫وســتمائة وريــاالن وســبعون هللــة مــن حســاب العميــل لديهــم ‪ ... /‬وذلــك‬\n‫بعــد قيــام األول بإنشــاء اشــتراك انترنــت حملفظــة العميــل دون علمــه‬\n‫ومــن ثــم الطلــب مــن زميلــه بتنفيــذه عــدة عمليــات بيــع ألســهم العميــل‬\n‫بحجــة أن العميــل طلــب منــه ذلــك مــع وعــده لهــم بإحضــاره مســتند أمــر‬\n‫بيــع موقــع مــن العميــل وبعــد أن يتــم بيــع األســهم يطلــب منهــم حتويــل‬\n‫مبالــغ البيــع إلــى حســاب العميــل اجلــاري املربــوط علــى احملفظــة ومــن ثــم‬\n‫يأتــي دور شــريكه الثانــي إجــراء عمليــات حتويــل مــن حســاب العميــل‬\n‫حلســاب األول وحلســاب عمــاء آخريــن أقربــاء لــأول متهيــدا لســحبها‬\n‫منهــم وتســليمها لــأول وكذلــك قيــام الثانــي بســرقة األرقــام الســرية‬\n‫لزمالئــه الصرافــن ســواء الــذي يعملــون معــه بنفــس الفــرع بحــي ‪ ....‬أو‬\n‫بالفــروع األخــرى وذلــك ســرقة األرقــام الســرية ملراقبــي الفــروع حتــى‬\n                      ‫يتمكــن مــن تنفيــذ تلــك اجلــواالت الغيــر مشــروعة ‪.‬‬\n‫وباســتجواب األول اعتــرف مبــا نســب إليــه حيــث أفــاد انــه كان يقــوم‬\n‫باالتصــال علــى زميلــه املدعــى عليــه الثانــي بطلــب حتويــل مبالــغ ماليــة‬\n‫متفرقــة مــن حســاب العميــل ‪ .... /‬إلــى حســابه الشــخصي كونــه يعمــل‬\n‫وســيط أســهم وكذلــك إلــى حســابات أخــرى تعــود ألقربائــه وكانــت‬\n                                                                     ‫كالتالــي ‪:‬‬\n‫‪ -1‬حتويــل مبلــغ قــدره (‪ )237.000‬مائتــن وســبعة وثالثــون ألــف ريــال‬\n                          ‫إلــى حســابه الشــخصي بتاريــخ ‪1429/10/19‬ه ـ‬\n‫‪ -2‬حتويــل مبلــغ قــدره (‪ )47.000‬ســبعة وأربعــون ألــف ريــال إلــى حســابه‬\n                                        ‫الشــخصي بتاريخ ‪1429/10/25‬هـ ‪.‬‬\n‫‪ -3‬حتويــل مبلــغ قــدره (‪ )340.000‬ثالثمائــة وأربعــون ألــف ريــال إلــى‬\n\n\n                                                                                      ‫‪234‬‬\n\f                                      ‫حســابه الشــخصي بتاريــخ ‪1429/11/4‬ه ـ‬\n      ‫‪ -4‬حتويــل مبلــغ قــدره (‪ )612.834‬ســتمائة واثنــا عشــر ألــف وثمامنائــة‬\n       ‫وأربعــة وثالثــون ريــال إلــى حســابه الشــخصي بتاريــخ ‪1429/11/4‬ه ـ‬\n      ‫‪ -5‬حتويــل مبلــغ قــدره (‪ )309.300‬ثالثمائــة وتســعة آالف وثالثمائــة‬\n                        ‫ريــال إلــى حســابه الشــخصي بتاريــخ ‪1429/11/17‬ه ـ‬\n      ‫‪ -6‬حتويــل مبلــغ قــدره (‪ )600.000‬ســتمائة ألــف ريــال إلــى حســابه‬\n                                             ‫الشــخصي بتاريــخ ‪1429/11/19‬ه ـ‬\n      ‫‪ -7‬حتويــل مبلــغ قــدره (‪ )577.000‬خمســمائة وســبعة وســبعون ألــف‬\n                        ‫ريــال إلــى حســابه الشــخصي بتاريــخ ‪1429/11/21‬ه ـ‬\n      ‫‪ -8‬حتويــل مبلــغ قــدره (‪ )600.000‬ســتمائة ألــف ريــال إلــى حســابه‬\n                                             ‫الشــخصي بتاريــخ ‪1429/12/29‬ه ـ‬\n      ‫‪ -9‬حتويــل مبلــغ قــدره (‪ )590.812‬خمســمائة وتســعون ألــف وثمامنائــة‬\n             ‫واثنــا عشــر ريــال إلــى حســابه الشــخصي بتاريــخ ‪1429/12/29‬ه ـ‬\n      ‫‪ -10‬حتويــل مبلــغ قــدره (‪ )783.059‬ســبعمائة وثالثــة وثمانــون ألــف‬\n      ‫وتسعة وخمسون ألف ريال إلى حسابه الشخصي بتاريخ ‪1430/1/3‬هـ‬\n      ‫‪ -11‬حتويــل مبلــغ قــدره (‪ )989.061‬تســعمائة وتســعة وثمانــون ألــف‬\n        ‫وواحــد وســتون ريــال إلــى حســابه الشــخصي بتاريــخ ‪1430/1/7‬ه ـ‬\n      ‫‪ -12‬حتويــل مبلــغ قــدره (‪ )674.000‬ســتمائة وأربعــة وســبعون ألــف ريــال‬\n                                   ‫إلى حســابه الشــخصي بتاريــخ ‪1430/2/21‬هـ‬\n      ‫‪ -13‬حتويــل مبلــغ قــدره (‪ )755.282‬ســبعمائة وخمســة وخمســون ألــف‬\n          ‫واثنــن وثمانــون ريــال إلــى حســابه الشــخصي بتاريــخ ‪1430/2/22‬ه ـ‬\n      ‫‪ -14‬حتويــل مبلــغ قــدره (‪ )839.274‬ثمامنائــة وتســعة وثالثــون ومائتــن‬\n      ‫وأربعة وسبعون ألف ريال إلى حسابه الشخصي بتاريخ ‪1430/2/28‬هـ‬\n\n\n‫‪235‬‬\n\f‫‪ -15‬حتويــل مبلــغ قــدره (‪ )870.000‬ثمامنائــة وســبعون ألــف ريــال إلــى‬\n                                 ‫حســابه الشــخصي بتاريــخ ‪1430/5/27‬ه ـ‬\n‫‪ -16‬حتويــل مبلــغ قــدره (‪ )980.000‬تســعمائة وثمانــون ألــف ريــال إلــى‬\n                                          ‫قريبــه ‪ .... /‬بتاريــخ ‪1430/10/14‬ه ـ‬\n‫‪ -17‬حتويــل مبلــغ قــدره (‪ )980.000‬تســعمائة وثمانــون ألــف ريــال إلــى‬\n                                       ‫قريبــه ‪ ....... /‬بتاريــخ ‪1430/10/12‬ه ـ‬\n‫‪ -18‬حتويــل مبلــغ قــدره (‪ )2.640.000.00‬مليونــان وســتمائة وأربعــون‬\n                ‫ألــف ريــال إلــى حســاب قريبــه‪ ..... /‬علــى فتــرات متفرقــة ‪.‬‬\n‫‪ -19‬حتويــل مبلــغ قــدره (‪ )8.435.000.00‬ثمانيــة ماليــن وأربعمائــة‬\n‫وخمســة وثالثــون ألــف ريــال مــن حســابه الشــخصي إلــى حســاب شــقيقه‬\n                                                       ‫‪ .....‬علــى فتــرات متفرقــة ‪.‬‬\n‫وأن جميــع تلــك العمليــات متــت مــن حســاب العميــل ‪ .... /‬دون‬\n‫علمــه وأنــه تصــرف بجميــع تلــك املبالــغ املاليــة والتــي بلــغ إجماليهــا‬\n‫(‪ )17.306602.70‬ســبعة عشــر مليون ـ ًا وثالثمائــة وســتة آالف ريــال‬\n‫وســتمائة وريــاالن وســبعون هللــة علــى نفســه حيــث قــام بتســديد ديــون‬\n‫خاصــة عليــه وعلــى بعــض أقاربــه وأن املســئولية علــى حتمــل ذلــك املبلــغ‬\n                   ‫تقــع عليــه دون غيــره وصــدق اعترافــه شــرع ًا بذلــك ‪.‬‬\n‫وباســتجواب الثانــي جــاءت أقوالــه مطابقــة ألقــوال األول وأفــاد أيضــا‬\n‫أنــه كان يقــوم بتحويــل تلــك املبالــغ حلســاب زميلــه األول وبعــض اقاربــه‬\n‫عــن طريــق قســائم حتويــل مــن حســاب إلــى حســاب ويقــوم بالتوقيــع علــى‬\n‫تلــك التحاويــل نيابــة عــن العميــل دون علمــه بطلــب منــه كمــا أضــاف‬\n‫أيضــا أنــه كان يقــوم بجميــع عمليــات التحاويــل البنكيــة باســتخدام‬\n‫األرقــام الســرية للصرافــن ومــدراء العمليــات دون علمهــم بذلــك وأن‬\n\n\n                                                                                        ‫‪236‬‬\n\f      ‫أجمالــي املبالــغ بعــد تدقيقهــا مــن قبــل مدققــي حســابات البنــك بلغــت‬\n      ‫(‪ )17.30660270‬ســبعة عشــر مليون ـ ًا وثالثمائــة وســتة آالف وســتمائة‬\n                            ‫وريــاالن وســبعون هللــة وصــدق اعترافــه بذلــك شــرع ًا‬\n                         ‫وبإحضار كال من ‪:‬الثالث والرابع واخلامس والسادس ‪.‬‬\n      ‫جــاءت أقوالهــم جميعــا متطابقــة حيــال عــدم علمهــم مبصــدر تلــك‬\n      ‫األمــوال التــي حتــول إلــى حســاباتهم ســوى أنهــم يعلمــون بأنهــا كانــت‬\n      ‫تتــم بواســطة قريبهــم ‪ .... /‬كونــه معلــوم لديهــم بأنــه يعمل وســيط أســهم‬\n      ‫لــدى البنــك وأنــه يطلــب منهــم ذلــك ويقــوم بســحبها منهــم حــال حتويلهــا‬\n                                  ‫إلــى حســاباتهم وعــدم اســتفادتهم مــن تلــك املبلــغ‪.‬‬\n                                 ‫وبإحضار موظفي شركة ‪ ....‬املصرفية كل من ‪:‬‬\n      ‫‪ ...... -1‬أفــاد بعــدم علمــه بتلــك التحاويــل البنكيــة التــي كانــت تتــم عــن‬\n      ‫طريــق الرقــم الســري اخلــاص بــه إال بعــد أن مت إبالغــه مــن قبــل البنــك‬\n      ‫وأن الثانــي أبلغــه بأنــه قــام بســرقة الرقــم الســري اخلــاص بــه واســتخدامه‬\n                                                                          ‫بتلــك التحاويــل ‪.‬‬\n      ‫‪ ..... -2‬أفــاد أنــه ســبق وأن ورده اتصــال هاتفــي مــن قبــل األول يطلــب‬\n      ‫منــه أن يقــوم بإجــراء عمليــة بيــع أســهم للعميــل ‪ .... /‬وأنــه قــام بإرســال‬\n      ‫أوامــر البيــع وأوامــر التحويــل إليــه وأنــه لــم يكــن يعلــم بــأن املتهــم قــام‬\n                                       ‫بالتوقيــع علــى تلــك األوامــر دون علــم العميــل ‪.‬‬\n                                    ‫‪ ..... -3‬جاءت أقواله مطابقه ألقوال زميله ‪. ... /‬‬\n      ‫جــاءت أيضــا أقوالهــم متطابقــة عــن عــدم علمهــم بتلــك التحاويــل‬\n      ‫البنكيــة التــي كانــت تتــم بواســطة أرقامهــم الســرية ‪ .‬وقــد أســفر‬\n      ‫التحقيــق عــن اتهــام األول والثانــي باســتغالل وظيفتهمــا لــدى مصــرف‬\n      ‫‪ ....‬وقيامهمــا باختــاس مبلــغ مالــي مــن حســاب عميــل دون علمــه أو‬\n\n\n‫‪237‬‬\n\f‫علــم إدارة املصــرف وذلــك بعــد التخطيــط والتنســيق املســبق بينهمــا‬\n‫وقيــام الثانــي بســرقة االرقــام الســرية لبعــض موظفــي البنــك ومراقبــي‬\n‫الفــروع إلجنــاز تلــك التحاويــل الغيــر مشــروعة للحســاب الشــخصي‬\n‫لزميلــه األول واتهــام الثالــث والرابــع واخلامــس والســادس بإعطــاء‬\n‫حريــة التصــرف لــأول بحســاباتهم الشــخصية ممــا ســهل عليــه عمليــة‬\n‫اختــاس تلــك األمــوال مــن حســاب العميــل دون علمــه واتهــام إدارة‬\n‫مصــرف ‪ ....‬باإلهمــال مبراقبــة حســابات العمــاء بشــكل دوري ممــا‬\n‫تســبب ذلــك بإجــراء عــدة عمليــات حتاويــل مــن حســاب العميــل لديهــم‬\n‫إلــى حســابات أخــرى دون اكتشــاف ذلــك إال بعــد وقــت متأخــر وذلــك‬\n                                                      ‫لألدلــة والقرائــن التاليــة ‪-:‬‬\n‫‪1‬ـ اعترافاتهــم املصدقــة شــرعا املــدون علــى الصفحــة رقــم (‪ ).....‬مــن‬\n                                            ‫دفتــر التحقيــق املرفــق رقــم (‪.)......‬‬\n‫‪ -2‬مــا ورد يف أقــوال شــقيق األول املــدون علــى الصفحــة رقــم (‪ ).....‬مــن‬\n                                               ‫دفتــر التحقيــق املرفــق رقــم (‪.).....‬‬\n‫‪3‬ـ مــا ورد يف أقربــاء األول لــكل مــن ‪ .... /‬و‪....‬بقيــام األول بتحويــل مبالــغ‬\n                                                                    ‫مالية لســحابهم ‪.‬‬\n‫‪ -4‬مــا ورد بأقــوال موظــف املصــرف ‪ ......‬بقيــام الثانــي باالعتــراف لديــه‬\n‫بأنــه قــام بســرقة الرقــم الســري اخلــاص بــه واســتخدامه بتلــك التحاويــل ‪.‬‬\n‫‪ -5‬مــا ورد يف أقــوال املوظــف ‪ ... /‬املــدون علــى الصفحــة رقــم (‪ ).....‬مــن‬\n                                          ‫دفتــر التحقيــق املرفــق لفــة رقــم (‪).....‬‬\n‫‪ -6‬مــا ورد يف أقــوال املوظــف ‪ ... /‬املــدون علــى الصفحــة رقــم (‪ ).....‬مــن‬\n                                          ‫دفتــر التحقيــق املرفــق لفــة رقــم (‪).....‬‬\n‫‪ -7‬مــا ورد يف بيــان التحاويــل البنكيــة املقدمــة مــن املصــرف بقيمتهــا‬\n\n\n                                                                                          ‫‪238‬‬\n\f                                   ‫املــدون أعــاه وتطابــق ذلــك مــع ورد باعترافهــم‪.‬‬\n      ‫‪ -8‬عــدم قيــام املصــرف بإتبــاع اللوائــح والقوانــن الصــادرة مــن مؤسســة‬\n                                                                 ‫النقــد العربــي الســعودي ‪.‬‬\n      ‫‪ -9‬عــدم قيــام قســم التدقيــق الداخلــي للمصــرف باالنتبــاه لتلــك‬\n                                                                    ‫التحاويــل الضخمــة ‪.‬‬\n      ‫وببحــث عــن ســوابقهم أتضــح عــدم وجــود ســوابق مســجلة تاريخــه‪.‬‬\n      ‫وحيــث إن مــا أقــدم عليــه املذكــورون فعــل محــرم ومعاقــب عليــه شــرع ًا‬\n      ‫أطلــب إثبــات مــا أســند إليهــم واحلكــم عليهــم بعقوبــة تعزيريــة لقــاء ذلــك‬\n      ‫(علمــا بــأن احلــق اخلــاص مــا زال قائمــا هــذه دعــواي وبعــرض ذلــك علــى‬\n      ‫ا إن مــا ذكــره املدعــي العــام عنــي كلــه‬        ‫املدعــى عليــه ‪....‬أجــاب قائ ـ ً‬\n      ‫ا فقــد اســتغللت وظيفتــي حيــث كنــت أعمــل‬              ‫صحيــح جملــة و تفصي ـ ً‬\n      ‫مشــرف صالــة األســهم يف مصــرف ‪ ....‬فــرع الــورود ثــم انتقلــت لفــرع ‪.....‬‬\n      ‫ثــم فــرع ‪ .....‬و قمــت بإنشــاء حســاب إنترنــت حملفظــة العميــل ‪ .....‬دون‬\n      ‫علمــه و إذنــه عــن طريــق املوظــف ‪ ....‬حيــث كانــت محفظتــه مجمــدة و‬\n      ‫ذات مبالــغ طائلــة وهــو مشــغول عنهــا و كنــت أجــرى عمليــات بيــع أســهم‬\n      ‫و أســيلها حلســاب ‪ ...‬اجلــاري املربــوط باحملفظــة و أطلــب مــن املدعــي عليه‬\n      ‫‪ ...‬حتويلهــا حلســابي حيــث أفهمــت املدعــى عليــه ‪ ...‬ان ‪ ...‬مــن أقاربــي و‬\n      ‫اطمــأن للوضــع ثقــة بــي و لطــول الفتــرة دون ظهــور شــكاوى ضــدي و‬\n      ‫اســتمر احلــال ذلــك قرابــة الســنة ثــم بــدأت أطلــب مــن املدعــى عليــه ‪...‬‬\n      ‫حتويــل املبالــغ املســيلة مــن أســهم احملفظــة املذكــورة لبعــض أقاربــي‬\n      ‫وهــم املدعــى عليهــم شــقيقي ‪ ..‬و ابــن ‪ ..‬و ‪ ...‬و ‪ ...‬حيــث حولــت لهــم املبالــغ‬\n      ‫املذكــورة يف الدعــوى دون علمهــم أو إذنهــم حيــث إني كلما حولت لهم‬\n      ‫مبلغـ ًا طلبــت منهــم حتويلــه حلســابي أو تســليمه لــي نقــد ًا دون أن يأخــذوا‬\n\n\n‫‪239‬‬\n\f‫منــه شــيئ ًا إ ّال شــقيقي ‪ ...‬فقــد فتحــت لــه حســابا باســمه و أنــا الــذي أوقــع‬\n‫عنــه ومعــي بطاقتــه وال يعلــم عنــه شــيئ ًا و أنــا الــذي أخذت املــال املذكور‬\n‫ا و ليــس للمدعــى عليهــم اآلخريــن عالقــة بــه هكــذا أجــاب و‬               ‫كام ـ ً‬\n‫ا إن مــا ذكــره املدعــي العام منــه الصحيح و‬          ‫أجــاب املدعــى عليــه ‪ ...‬قائـ ً‬\n‫منــه غيــر الصحيــح و الصحيــح أن املدعــى عليــه ‪ ....‬كان زميــل عمــل لــي‬\n‫اخلاصــة و كنــت أعمــل يف مصــرف ‪....‬‬      ‫ّ‬      ‫حيــث كنــت آتيــه لبيــع أســهمي‬\n‫يف غيــر الفــرع الــذي يعمــل املدعــى عليــه وكان يتصــل بــي و يطلــب منــي‬\n‫حتويــل املبالــغ املســيلة مــن بيــع األســهم يف محفظــة ‪ ....‬حلســابه و حســاب‬\n‫أقاربــه وكان دوري كتابــة أوراق التحويــل للموظفــن ليقوموا بعمليات‬\n‫التحويــل ولــم أقــم منهــا إ ّال بعمليتــي حتويــل األولــى حلســاب املدعــى عليــه‬\n‫‪ ...‬بتســعمائة و ثمانــن ألــف و الثانيــة بتســعمائة و ثمانــن حلســاب املدعــى‬\n‫عليــه ‪ ....‬و قــد وقعــت يف خانــة العميــل عــدة مــرات يف عمليــات التحويــل‬\n‫ـرية لزمالئــي الصرافــن أو‬        ‫و أمــا مــا ذكــره مــن ســرقة األرقــام السـ ّ‬\n‫بالفــروع األخــرى أو املراقبــن فغيــر صحيــح و قــد اعترفــت بذلــك تغريــرا‬\n‫مــن محقــق املصــرف الــذي حقــق معــي هكــذا و أجــاب املدعــى عليــه‬\n‫‪ . ....‬باملصادقــة علــى حتويــل املدعــى عليــه ‪ ...‬علــى حســابه تســعمائة‬\n‫و ثمانــن ألــف ريــال دون علمــه وقــال ‪ ....‬لــي إنهــا أرباحــه يف األســهم‬\n‫و طلــب منــي تســليمها لــه عــن طريــق حتويــل تســعمائة ألــف حلســابه يف‬\n‫بنــك ‪ ........‬و ثمانــون ألــف ســلمتها لــه نقــدا ولــم آخــذ منهــا شــيئ ًا علم ـ ًا‬\n‫ان تســليمي املبلــغ و حتويلــي لــه للمدعــى عليــه ‪ ...‬كان بعــد حتويلــه لــي‬\n‫مباشــرة هكــذا أجــاب و أجــاب املدعــى عليــه ‪ ...‬باملصادقــة علــى حتويــل‬\n‫املدعــى عليــه ‪ ....‬علــى حســابه مبالــغ علــى ثــاث دفعــات مجموعهــا مبلغـ ًا‬\n‫قــدره مليونــان و ســتمائة و أربعــون ألــف ريــال و أضــاف أن بــن كل‬\n\n\n                                                                                            ‫‪240‬‬\n\f      ‫حتويلــن قرابــة شــهرين وهــو قريــب لــي و عنــد حتويلــه املبلــغ يتصــل بــي‬\n      ‫مباشــرة ويقــول إنهــا أربــاح لــه يف األســهم و يطلــب منــي حتويلهــا حلســابه‬\n      ‫و أحولــه مباشــرة و لــم آخــذ منهــا شــيئ ًا علمـ ًا أنــي لــم أطلــب منــه و لــم آذن‬\n      ‫لــه بالتحويــل وال أعلــم بــه إ ّال بعــد اتصالــه بــي هكــذا أجــاب و أجــاب‬\n      ‫املدعــى عليــه وكالــة ‪ ....‬يحمــل ســجل مدنــي رقــم ( ‪ ) ....‬الوكيــل عــن‬\n      ‫املدعــى عليــه ‪ ...‬مبوجــب الوكالــة الصــادرة مــن كاتــب وزارة الداخليــة‬\n      ‫املكلــف برقــم ‪ 359‬يف ‪1433/03/14‬ه ـ املخــول لــه فيهــا حــق املطالبــة‬\n      ‫و املرافعــة وحضــور اجللســات إلــخ باملصادقــة علــى حتويــل املدعــى عليــه‬\n      ‫‪ ....‬حلســاب موكلــه ‪ ...‬مبلــغ تســعمائة و ثمانــن ألــف يف شــهر ذي احلجــة‬\n      ‫بــدون علمــه وال أذنــه وطلــب منــه حتويلهــا لــه وقــام موكلــي مباشــرة‬\n      ‫بكتابــة شــيك باملبلــغ ثــم طلــب املدعــى عليــه ‪ ....‬مــن موكلــي حتويلهــا‬\n      ‫حلســابه عــن طريــق التحويــل فحولهــا موكلــي لــه و علــم موكلــي أثنــاء‬\n      ‫التحويــل أن املبلــغ املذكــور قــد حــول حلســابه مــن حســاب ‪ .....‬فحــول‬\n      ‫املبلــغ للمدعــى عليــه ‪ ....‬ثــم ذهــب موكلــي إلــى ‪ ....‬وهــو مــن أقاربــه‬\n      ‫ماليــة فقــال ال‬\n                    ‫فســأله هــل بينكــم و بــن املدعــى عليــه ‪ ....‬تعامــات ّ‬\n      ‫فأخبــره موكلــي باخلبــر فانكشــف أمــره حينمــا تقــدم ‪ ...‬بشــكواه و‬\n      ‫كان موكلــي هــو الــذي اكتشــف هــذا االختــاس ولــم يأخذ مــن املبلغ‬\n      ‫شــيئ ًا هكــذا أجــاب علــى ذلــك طلــب احلاضــر ‪ ....‬حامــل الســجل املدنــي‬\n      ‫ا عــن املدعــى عليــه احلاضــر ‪ ...‬مبوجــب‬        ‫رقــم ( ‪ ) ...‬حــال كونــه وكيـ ً‬\n      ‫صــك الوكالــة رقــم ‪ 331‬يف ‪1431/3/29‬ه ـ الصــادرة مــن كاتــب عدل‬\n      ‫وزارة الداخليــة و املتضمنــة حــق املرافعــة و املدافعــة و اإلقــرار و اإلنــكار‬\n      ‫و الصلــح ‪...‬إلــخ وقــال إن مــا ذكــره املدعــي العــام مــن اتهــام موكلــي‬\n      ‫الســرية ملوظفــي املصــرف و مراقبيــه غيــر صحيــح ألنهــا‬          ‫بســرقة األرقــام ّ‬\n\n‫‪241‬‬\n\f‫تخالــف نظــام املصــرف الــذي ينــص علــى أن مــا زاد علــى مبلــغ التحويــل‬\n‫علــى خمســن ألــف ريــال البــد مــن توقيــع املشــرف عليــه يدويـ ًا و كذلــك‬\n‫ميكــن كشــف تلــك احلقيقــة عــن طريــق كاميــرات املراقبــة املوجــودة‬\n‫باملصــرف و يــدل الســتبعاد االتهــام أن موكلــي قــد عمــل يف فرعــن‬\n‫مختلفــن للبنــك فكيــف يجــري عمليــات التحويــل مــن أرقــام املوظفــن‬\n‫دون ان يفتضــح طيلــة هــذه الفتــرة التــي جتــاوزت ســنة كاملــة كمــا‬\n‫أن هنــاك أطراف ـ ًا لــم تتــم إدانتهــم مــع وضــوح مشــاركتهم يف جرميــة‬\n‫االختــاس وهــم موظفــون يف مصــرف ‪ ....‬وهــم ‪ ....‬الــذي أنشــأ بطلــب‬\n‫مــن املدعــى عليــه ‪ ...‬حســاب إنترنــت حملفظــة ‪ ...‬و املوظــف ‪ ....‬و ‪ ...‬و‬\n‫‪ ...‬و ‪ ....‬وهــؤالء جميع ـ ًا قامــوا بعمليــة بيــع و شــراء و حتويــل مــن و إلــى‬\n‫محفظــة ‪ ...‬االســتثمارية دون علمــه و بتوجيــه مــن املدعــى عليــه ‪ ....‬وهــي‬\n‫أخطــر عمليــة يف االختــاس وعليــه فأطلــب تبرئــة موكلــي أســوة بهــم‬\n‫هكــذا قــرر وقــدم مذكــرة بذلــك جــرى إرفاقهــا باملعاملــة كمــا طلــب‬\n‫املدعــى عليهــم ‪...‬و ‪ ...‬و ‪ ....‬اإلضافــة ملــا ذكــر فــأذن لهــم فقالــوا نحــن ال‬\n‫القضيــة لعــدم علمنــا أو رضانــا بعمليــات التحويــل‬  ‫ّ‬         ‫تلحقنــا إدانــة يف هــذه‬\n‫التــي قــام بهــا املدعــى عليــه ‪ ....‬و لتســاهل البنــك و تفريطــه حيــث لــم‬\n‫يشــعرنا بدخــول هــذه املبالــغ يف حســابنا مــع كثرتهــا و لــم يقــم مبراقبــة‬\n‫احلســابات و طول فترة االختالس دون أن يكتشــفها إال بعد اكتشــاف‬\n‫املدعــى عليــه ‪ ...‬لهــا و متكــن موظفــن مــن حســابات العمــاء و عليــه‬\n‫فنطلــب إثبــات براءتنــا هكــذا قــرروا و قدمــوا مذكــرة جــرى إرفاقهــا‬\n‫باملعاملــة كمــا حضــر ‪ ....‬حامــل الســجل املدنــي رقــم ( ‪ ) ...‬و ‪....‬حامــل‬\n‫الســجل املدنــي ر قــم ( ‪ ) ...‬حــال كونهمــا وكيلــن عــن ‪ ....‬بصفتــه‬\n‫ا عــن ‪ .... ...‬و ‪ ....‬و ‪ ...‬و ‪ .... ....‬و ‪ ....‬و ‪ ....‬و ‪ .... ....‬و ‪ .... ..‬بصفتــه‬\n                                                                                   ‫وكي ـ ً‬\n\n\n                                                                                              ‫‪242‬‬\n\f      ‫مــن أعضــاء مجلــس إدارة شــركة ‪ ......‬مبوجــب صــك الوكالــة رقــم‬\n      ‫‪ 7189‬و ‪ 7190‬وكالهمــا يف ‪1432/12/24‬ه ـ والصــادران مــن كاتــب‬\n      ‫عــدل وزارة التجــارة والصناعــة واملتضمنتــان حــق املرافعــة واملدافعــة‬\n      ‫واملخاصمــة واجلــرح والتعديــل واالعتراض‪....‬إلــخ والوكالــة األولــى‬\n      ‫خاصــة بالوكيــل ‪ ...‬وادعيــا‬   ‫ّ‬       ‫خاصــة بالوكيــل ‪ ...‬والوكالــة الثانيــة‬  ‫ّ‬\n      ‫قائلــن لقــد قــام املدعــى عليــه ‪ ....‬باختــاس ثالثمائــة واثنــن وثالثــن‬\n      ‫ألــف ومائــة وأربعــة وثمانــن ســهم ًا مــن أســهم مصــرف‪ ....‬مــن محفظــة ‪....‬‬\n      ‫التــي يف مصــرف ‪ ....‬وتســييلها و أخــذ قيمتهــا بالتعــاون مــع باقــي املدعــى‬\n      ‫عليهــم و قــد قامــت الشــركة موكلتــي بشــراء أســهم بعــدد األســهم‬\n      ‫املســروقة و نوعهــا و تســليمها حملفظــة ‪ ...‬املذكــور ونتــج عــن ذلــك دفــع‬\n      ‫موكلتــي مبلــغ خمســة وعشــرين مليونـ ًا وســتمائة و خمســة وثالثــن ألف‬\n      ‫و ســبعمائة وســتة و أربعــن ريــا ًال وخمــس وخمســن هللــة تفصيلهــا علــى‬\n      ‫ما يلي ‪ /1 :‬خمســة وعشــرين مليون ًا ومائتان وســتة آالف و مائة و ســبعة‬\n      ‫آالف وثــاث و تســعون هللــة قيمــة األســهم املشــتراة ‪ /2 .‬ســبعمائة ريــال‬\n      ‫أجــرة اإلنترنــت لهــذه العمليــة‪ /3 .‬مليــون و مائــة واثنــان و تســعون ألف ـ ًا‬\n      ‫وائتــان و ثــاث و عشــرون ريــا ًال وخمــس وعشــرون هللــة أربــاح األســهم‬\n      ‫املســروقة يــوم توزيــع األربــاح الــذي اعتمــده مجلــس اإلدارة وقــد خصــم‬\n      ‫منــه مبلــغ ســبعمائة و ثالثــة و ســتني ألــف و مائتــن وأربعــة و ثمانــن‬\n      ‫ـاق يف احلســاب االســتثماري‬      ‫ألــف ريــال وأربــع و ســتني هللــة وهــو مبلــغ بـ ٍ‬\n      ‫للعميــل ‪ ....‬املذكــور ومجمــوع مــا تطلبــه الشــركة موكلتنــا مبلغ ًا قدره‬\n      ‫خمســة و عشــرون مليون ـ ًا وســتمائة وخمســة وثالثــون ألف ـ ًا وســبعمائة‬\n      ‫وســتة وأربعــون ريــا ًال وخمســة و خمســون هللــة نطلــب إلــزام املدعــى‬\n      ‫عليهــم دفعهــا بالتضامــن للشــركة موكلتنــا هــذه دعوانــا وبعــرض‬\n\n\n‫‪243‬‬\n\f‫ذلــك علــى املدعــى عليهــم صــادق املدعــى عليــه ‪ ...‬علــى دعــوى املدعــي‬\n‫ا و نفــى اشــتراك باقــي املدعــى عليهــم معــه وقــال‬      ‫اخلــاص جملــة و تفصيـ ً‬\n‫أحتمــل كامــل املبلــغ الــذي يدعيــه املدعــي اخلــاص و ليــس لباقــي‬       ‫ّ‬    ‫إننــي‬\n‫املدعــى عليهــم عالقــة بــه ألنــي أحــول لهــم و أطلــب حتويلــه حلســابي أو‬\n‫نقــد َا و آخــذه منهــم هكــذا أجــاب و بســؤال املدعــى عليهــم الباقــن عــن‬\n‫ا إنــه لــم يدخــل يف‬  ‫دعــوى املدعــي اخلــاص أجــاب املدعــى عليــه ‪ ...‬قائ ـ ً‬\n‫حســابي مــن املبالــغ التــي يدعيهــا املدعــي اخلــاص شــيء و أجــاب باقــي‬\n‫املدعــى عليهــم عــدا ‪ ...‬و ‪ ..‬قائلــن نعــم لقــد أدخــل املدعــى عليــه ‪ ....‬يف‬\n‫حســاباتنا مــا ذكرنــاه يف جــواب الدعــوى العامــة و قــد ســلمناها لــه‬\n‫كاملــة و ليــس يف ذمتنــا منهــا شــيء هكــذا أجابــوا ثــم أضــاف املدعــى‬\n‫ا إن هنــاك أطراف ـ ًا‬   ‫عليــه وكالــة ‪ ...‬الوكيــل عــن املدعــى عليــه ‪ ...‬قائ ـ ً‬\n‫لــم يشــملهم االتهــام يف الدعــوى العامــة كمــا ذكرتهــم وهــم مــن أجــرى‬\n‫التحويــات و كذلــك املدققــون للحســابات اليوميــة يف البنــك و أطلــب‬\n‫تبرئــة موكلــي مــن احلــق اخلــاص كمــا لــم يطالــب املدعــي اخلــاص هــؤالء‬\n‫اليوميــة للنظــر يف عملية‬\n                      ‫ّ‬           ‫و أطلــب املدعــي اخلــاص بكشــوفات احلســابات‬\n‫التدقيــق و غيرهــا و كذلــك املخالفــة بــن توقيــع محولــي املبالــغ مــن‬\n‫حســاب ‪...‬حلســابات املدعــى عليهــم التــي تخالــف توقيــع ‪ ...‬و كيــف مت‬\n‫الســكوت علــى ذلــك مــن قبــل املصــرف هكــذا قــرر ثــم جــرى ســؤال‬\n‫املدعــي اخلــاص وكالــة ألديــك تفصيــل لعمليــات التحويــل مــن حســاب‬\n‫‪ ...‬إلــى حســابات املدعــى عليهــم و حركتهــا فقــال نعــم أمــا املدعــى عليــه‬\n                          ‫‪ .......‬فقــد ُحـ ّـول إلــى حســابه مــن حســاب ‪................‬‬\n‫يف ‪1430/12/ 6‬ه ـ مبلغ ـ ًا قــدره تســعمائة و ثمانــون ألــف ريــال ومت‬\n‫ســحبه بشــيك مصــريف وأمــا املدعــى عليــه ‪ ....‬فقــد حــول إلــى حســابه‬\n\n\n                                                                                              ‫‪244‬‬\n\f      ‫مــن حســاب ‪ ...‬يف ‪1430/10/ 14‬ه ـ مبلغ ـ ًا قــدره تســعمائة و ثمانــون‬\n      ‫ألــف ريــال ســحبت يف نفــس اليــوم بأمــر صــرف نقــد ًا و أمــا املدعــى‬\n      ‫عليــه ‪ ....‬فقــد حــول لــه مــن حســاب ‪ ....‬يف ‪1430/7/ 25‬ه ـ مبلغـ ًا قــدره‬\n      ‫ثمامنائــة وثمانــون ألــف ريــال حــول يف نفــس اليــوم مائــة ألــف ريــال ل‪...‬و‬\n      ‫ســبعمائة و ثمانــون ألــف ريــال ســحبت يف نفــس اليــوم بأمــر صــرف‬\n      ‫نقــد ًا و يف ‪1430/7/27‬ه ـ حــول يف حســابه مــن حســاب ‪...‬ثمامنائــة و‬\n      ‫ثمانــون ألــف ريــال ســحبت يف نفــس اليــوم ســتمائة و ثمانــون ألــف ريــال‬\n      ‫ومائــة وتســعة و تســعون ألــف ريــال كالهمــا بأمــر صــرف نقــد ًا و بقــي‬\n      ‫ألــف و يف يــوم ‪1430/9/3‬ه ـ حــول حلســابه مــن حســاب ‪ ....‬ثمامنائــة‬\n      ‫وثمانــون ألــف ريــال ســحبت يف نفــس اليــوم ثالثــون ألــف و ثمامنائــة و‬\n      ‫خمســون ألــف ريــال نقــد ًا بأمــر صــرف أمــا املدعــى عليــه أمــا املدعــى‬\n      ‫عليــه ‪ ....‬فلــم يحــول مــن حســاب ‪ ...‬حلســابه شــيء هكــذا أجــاب ثــم‬\n      ‫جــرى ســؤال املدعــي اخلــاص هــل ميكــن ألحــد موظفــي املصــرف أن‬\n      ‫يدخــل حلســاب أحــد العمــاء ويجــري عليــه عمليــات مصرفيــة دون إذن‬\n      ‫صاحبــه أو علمــه فقــال نعــم ولكنهــا مــن بــاب خيانــة األمانــة و البنــك‬\n      ‫مينــع ذلــك أشــد املنــع ويحاســب عليــه ثــم جــرى ســؤال املدعــي اخلــاص‬\n      ‫هــل ميكــن ألحــد موظفــي املصــرف أن ينشــأ حســاب ًا ألحــد األشــخاص‬\n      ‫دون علــم هــذا الشــخص و يوقــع عنــه و يجــري العمليــات عليــه فقــال نعــم‬\n      ‫إذا كان هنــاك صــورة لبطاقــة األحــوال و لكــن هــذا أيض ـ ًا مــن بــاب‬\n      ‫خيانــة األمانــة و كذلــك املصــرف مينــع ذلــك و يحاســب عليــه ثــم جــري‬\n      ‫ســؤاله كيــف اكتشــفت عمليــة االختــاس محــل الدعــوى و متــى فقــال‬\n      ‫اكتشــفت حــن قــدم ‪ ...‬شــكوى بذلــك وكان ذلــك بعــد أحــد عشــر‬\n      ‫شــهر ًا مــن بدايــة عمليــات االختــاس هكــذا أجــاب ثــم جــرى ســؤال‬\n\n\n‫‪245‬‬\n\f‫املدعــى عليــه ‪ ...‬هــل أجريــت عمليــات مصرفيــة علــى حســابك الــذي‬\n‫تذكــر أن الــذي أنشــأه و اســتعمله شــقيقك املدعــى عليــه ‪ ..‬فقــال لــم‬\n‫أجــر أي تعامــل إ ّال مــرة واحــدة اتصــل بــي املدعــى عليــه أخــي ‪ ..‬و قــال‬\n‫احضــر لــي يف مصــرف ‪ ....‬فــرع ‪ .....‬و ســلمني طلــب صــرف و قــال ســلمه‬\n‫لقســم التميــز فســلمته لهــم و أعطونــي مائــة ألــف ريــال و طلــب منــي‬\n‫املدعــى عليــه أخــي ‪ ...‬أن أســلم هــذا املبلــغ لشــخص وصــف لــي مكانــه‬\n‫فذهبــت لــه و أعطيتــه و كنــت وقتهــا طالبـ ًا يف الكليــة التقنيــة و ليــس‬\n‫لــدي حســاب إ ّال حســاب طالــب يف بنــك ‪ ........‬و اهلل إننــي ال أعلــم عــن‬\n‫حســابي الــذي يف مصــرف ‪ ....‬فــرع ‪ ....‬و إمنــا لــي حســاب يف مصــرف ‪....‬‬\n‫فــرع ‪ ....‬و التحويــات التــي يف حســابي يف مصــرف ‪ ....‬فــرع ‪ ......‬جميعهــا‬\n‫مــن حســاب املدعــى عليــه أخــي ‪ ...‬و ليــس فيهــا حتويــل مــن حســاب ‪...‬‬\n‫و املدعــى عليــه أخــي ‪ ...‬هــو الــذي ابتالنــي هكــذا أجــاب ثــم جــرى‬\n‫ســؤال املدعــى عليــه ‪ ....‬هــل كنــت تعــرف حــال املدعــى عليــه ‪ ...‬مــن‬\n‫وقــت طويــل فقــال نعــم هــو قريبــي و أعــرف أن حالتــه املاديــة متوســطة‬\n‫ثــم بــدأ يشــتغل يف األســهم و بــدأت أحلــظ مــن خــال كالمــه أن حالتــه‬\n‫القضيــة بســنة أو ســنتني هكــذا أجــاب ثــم جــرى‬ ‫ّ‬     ‫ميســورة و ذلــك قبــل‬\n‫ســؤال املدعــى عليــه وكيــل ‪ ...‬هــل لديــك البينــة علــى إخبــار موكلــك‬\n‫‪ ....‬بتحويــل املدعــى عليــه ‪ ....‬مــن حســاب ‪ ...‬حلســابك فقــال نعــم و ســوف‬\n‫أحضرهــا يف اجللســة القادمــة ثــم جــرى ســؤال وكيــل املصــرف املدعيــن‬\n‫باحلــق اخلــاص هــل تعلمــان مــن هــو الــذي أخبــر ‪ ...‬بحقيقــة االختــاس مما‬\n‫حــدا بــه إلــى تقــدمي الشــكوى للمصــرف فقــال ال كمــا قــدم املدعــى‬\n‫عليــه وكالــة ‪ ...‬مذكــرة بتفصيــل مــا ذكــره يف اجللســة و جــرى إرفاقهــا‬\n‫باملعاملــة و إلحضــار بينــة املدعــى عليــه ‪ ...‬جــرى رفــع اجللســة و أجلــت‬\n\n\n                                                                                    ‫‪246‬‬\n\f      ‫ليــوم الثالثــاء القــادم الســاعة العاشــرة و وصلــى اهلل علــى نبينــا محمــد‬\n      ‫وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/01/20‬ه ـ احلمــد هلل وحــده‬\n      ‫وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة بالريــاض ففــي يــوم‬\n      ‫األحــد ‪1434/1/25‬ه ـ افتتحــت اجللســة الثانيــة و النصــف ظهــر ًا و فيهــا‬\n      ‫حضــر املدعــى عليــه ‪ ...‬وأحضــر شــاهد ًا هــو ‪ ....‬يحمــل ســجل مدنــي رقــم‬\n      ‫ا عمــري‬     ‫(‪ )....‬و طلــب ســماع مــا لديــه و بســؤاله عمــا لديــه أجــاب قائ ـ ً‬\n      ‫اثنــان وأربعــون ســنة و أســكن يف الريــاض و أعمــل يف األعمــال احلــرة‬\n      ‫و أحمــل املؤهــل الثانــوي و ال تربطنــي باملدعــى عليهــم عالقــة و أشــهد‬\n      ‫ا هــل بــن‬    ‫بــاهلل أن املدعــى عليــه ‪ ...‬أتانــي يف مكتبــي و ســألني قائ ـ ً‬\n      ‫والديــك و املدعــى عليــه ‪ ....‬أي تعامــل مالــي فقلــت ال فأخبرنــي أنــه قــد‬\n      ‫جــاءه حتويــل مالــي مببلــغ تســعمائة ألــف ريــال تقريبـ ًا و أن املدعــى عليــه‬\n      ‫‪ ....‬اتصــل بــه و طلــب منــه حتويلــه حلســابه و كتــب لــه شــيك ًا باملبلــغ‬\n      ‫و عندمــا ســأل املدعــى عليــه ‪ ...‬عــن التحويــل أفيــد مــن البنــك أنــه مــن‬\n      ‫حســاب والــدي فلمــا أخبرنــي بذلــك أخبــرت والــدي و تقدمنــا بشــكوى‬\n      ‫ملصــرف ‪ ....‬وأشــهد بــاهلل أن الــذي اكتشــف عمليــة االختــاس هــو‬\n      ‫الســابق الشــيخ ‪ ....‬بطلــب‬    ‫املدعــى عليــه ‪ ....‬و قــد حضــرت للقاضــي ّ‬\n      ‫الســجن و كذلــك ذهبــت حملكمــة االســتئناف‬            ‫تبرئتــه و إخراجــه مــن ّ‬\n      ‫لهــذا الغــرض هــذا مــا لــدي و بــه أشــهد و لطلــب باقــي أطــراف الدعــوى‬\n      ‫جــرى رفــع اجللســة إلــى يــوم الثالثــاء ‪1434/1/27‬ه ـ و أغلقــت اجللســة‬\n      ‫الســاعة الواحــدة ظهــر ًا وصلــى اهلل وســلم علــى نبينــا محمــد و علــى آلــه‬\n      ‫و صحبــه وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫حــرر يف ‪1434/01/25‬ه ـ ويف جلســة اخــرى حضــر ‪ ....‬بالهويــة رقــم‬\n      ‫‪ ...‬و ‪ ....‬بالهويــة رقــم ‪ ....‬وشــهدا بعدالــة وثقــة الشــاهد ‪ ....‬وإلحضــار‬\n\n\n‫‪247‬‬\n\f‫املدعــى عليهــم جــرى رفــع اجللســة وصلــى اهلل علــى نبينــا محمــد وعلــى‬\n                                    ‫آلــه وصحبــه وســلم حــرر يف ‪1434/01/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض ففــي يــوم الثالثــاء املوافــق‪ 1434/01/27‬ه ـ وفيهــا حضــر‬\n‫‪ ...‬بالهويــة رقــم ‪ ....‬و ‪ ....‬بالهويــة رقــم ‪....‬وشــهدا بعدالــة وثقــة الشــاهد‬\n‫‪ ....‬وإلحضــار املدعــى عليهــم جــرى رفــع اجللســة وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/01/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالرياض افتتحت اجللسة الساعة الواحدة ظهر ًا و فيها حضر األطراف‬\n‫احلاضــرون يف اجللســة الســابقة و حضــر ‪ ....‬يحمــل ســجل مدنــي رقم (‪)....‬‬\n‫ال عن ‪ .... .....‬و ‪ ....‬و ‪ ....‬و‪ ....‬و ‪ ...‬و ‪ ....‬و ‪....‬‬\n                                                      ‫الوكيل عن ‪ ....‬بصفته وكي ً‬\n‫املصرفيــة لالســتثمار‬\n                  ‫ّ‬            ‫و‪ ....‬بصفتــه مــن أعضــاء مجلــس إدارة شــركة ‪....‬‬\n‫مبوجــب صــك الوكالــة رقــم (‪ )7192‬يف ‪1432/12/24‬ه ـ جلــد ‪261‬‬\n‫والصــادرة مــن كاتــب عــدل وزارة التجــارة و الصناعــة و املتضمنــة حــق‬\n‫املرافعــة و املدافعــة و املخاصمــة و اجلــرح و التعديــل و االعتــراض ‪....‬إلــخ‬\n‫و جــرى عــرض الدعــوى العامــة علــى وكيلــي مصــرف ‪ ....‬و أنكــرا‬\n‫إهمــال املصــرف و قــال إن الســبب احلقيقــي للجرميــة هــو ضعــف نفــس‬\n‫املدعــى عليهــم موظفــي املصــرف ‪ ...‬و ‪ ...‬و خيانتهــم و أن املصــرف ال‬\n‫يتحمــل شــيئ ًا هكــذا أجــاب و بعــرض شــهادة الشــاهد ‪ ....‬علــى املدعــي‬\n‫اخلــاص وكالــة قــال ال أعــرف الشــاهد و ال أقــول يف شــهادته شــيئ ًا‬\n‫فجــرى ســؤاله هــل ترغبــون يف أخــذ أميــان املدعــى عليهــم عــدا ‪ ...‬علــى‬\n‫عــدم أخذهــم شــيئ ًا مــن املبالــغ الناجتــة عــن االختــاس فقــال ال نرغــب‬\n‫ذلــك جــرى االطــاع علــى إقــرار املدعــى عليــه ‪ ...‬املصـ ّـدق شــرع ًا علــى‬\n\n\n                                                                                       ‫‪248‬‬\n\f      ‫صفحــة (‪ )12‬لفــة (‪ )11‬و املتضمــن حتويلــه مبلــغ ســبعة عشــر مليــون و‬\n      ‫ســتة آالف و ســتمائة و ريالــن و ســبعني هللــة مــن حســاب ‪ ....‬بعــد طلــب‬\n      ‫املدعــى عليــه ‪ ....‬و أن طريقــة التحويــل عــن طريــق قســائم حتويــل مــن‬\n      ‫حســاب إلــى حســاب و أنــه كان يقــوم بالتوقيــع مــكان العميــل و علــى‬\n      ‫ضــوء ذلــك يتــم التحويــل و كان التحويــل حلســاب ‪ ...‬و بعــض أقاربــه‬\n      ‫إ‪.‬ه ـ بتصــرف كمــا ألفيــت قولــه علــى صفحــة (‪ )7‬لفــة رقــم (‪ )1‬أنــه‬\n      ‫ـاص بهــم‬\n             ‫الســري اخلـ ّ‬‫يقــوم بالتحويــل عــن طريــق الصرافــن ملعرفــة الرقــم ّ‬\n      ‫وذلــك بحكــم مبــدأ الثقــة بينهــم إ‪.‬ه ـ بتصــرف و بعرضــه عليــه قــال ذلــك‬\n      ‫كلــه غيــر صحيــح و إمنــا هــو تغريــر مــن محقــق البنــك ثــم جــرى ســؤال‬\n      ‫املدعــى عليــه ‪ ....‬هــل تعلــم بتصــرف أخيــك املدعــى عليــه ‪ ...‬بالتصــرف‬\n      ‫القضيــة فبنــاء علــى مــا ســلف مــن‬\n                                           ‫ّ‬      ‫بحســابك فقــال ال لــم أعلــم إ ّال بعــد‬\n      ‫العامــة‬\n         ‫ّ‬     ‫الدعــوى و اإلجابــة و إلقــرار املدعــى عليــه ‪ ...‬مبــا جــاء يف الدعــوى‬\n      ‫واخلاصــة مــن اســتغالله وظيفتــه و اختالســه ثالثمائــة و اثنــن و ثالثــن‬    ‫ّ‬\n      ‫ألــف و مائــة و أربعــة و ثمانــن ســهم ًا مــن أســهم ‪ ....‬مــن محفظة ‪ ....‬وإقرار‬\n      ‫الســرية لبعــض‬ ‫املدعــى عليــه ‪ ...‬باســتغالل وظيفتــه و اســتخدامه األرقــام ّ‬\n      ‫موظفــي املصــرف دون علمهــم و رجوعــه عــن إقــراره و لظهــور اشــتراكه‬\n      ‫مــع املدعــى عليــه ‪ ...‬يف االختــاس املذكــور عــن طريــق التحويــات التــي‬\n      ‫أجراهــا مــن حســاب ‪ ...‬حلســابات املدعــى عليــه ‪ ...‬و ‪ ...‬و ‪ ...‬وفــق إقــراره و‬\n      ‫التوقيــع عــن العميــل و لضخامــة املبالــغ التــي حولهــا و تكــرار حتويلهــا‬\n      ‫دون علــم و إذن صاحــب احلســاب ‪...‬أو حضــوره ممــا يبعــد أن يكــون‬\n      ‫ذلــك التحويــل ثقــة مــن املدعــى عليــه ‪ ...‬بســامة الوضــع و ألنــه لــم يثبــت‬\n      ‫أخــذه لشــيء مــن هــذه املبالــغ و ألن األصــل عدمــه وإلحلــاق املدعــى عليــه‬\n      ‫‪ ..‬الضــرر مبــن حــول إلــى حســاباتهم و اســتغاللها و لتعارضــه مــع حــق‬\n\n\n‫‪249‬‬\n\f‫القرابــة و الرحــم ولظهــور تفريــط املصــرف و إهمالــه يف عدم اكتشــاف‬\n‫عمليــة االختــاس التــي دامــت أكثــر مــن عشــرة أشــهر مــن قبــل موظفيه‬\n‫و اكتشــاف التالعــب بحســابات العمــاء و ألن اكتشــافه لذلــك كان‬\n‫بعــد شــكوى صاحــب احملفظــة املختلــس منهــا و خلطــورة هــذا األمــر‬\n‫وحرمتــه و معارضتــه لضــرورة حفــظ املــال و لعــدم قبــول رجــوع املدعــى‬\n‫عليــه ‪ ...‬عــن إقــراره الــذي صــادق عليــه شــرع ًا و لتوافــق داللــة ظاهــر‬\n‫احلــال مــع أصــل االختيــار و الرضــى يف أقــوال املكلــف و لكــون فعــل‬\n‫املدعــى عليهمــا ‪ ...‬و ‪ ...‬مــن االعتــداء احملــرم بقولــه تعالــى ( وال تعتــدوا‬\n‫إن اهلل ال يحــب املعتديــن ) و قــول الرســول صلــى اهلل عليــه وســلم يف‬\n‫الصحيحــن ‪ ( :‬إن دماءكــم و أموالكــم و أعراضكــم عليكــم‬\n‫حــرام كحرمــة يومكــم هــذا يف بلدكــم هــذا يف شــهركم هــذا ) و‬\n‫ملشــروعية تعزيــر املدعــى عليهمــا ‪ ...‬و ‪ ....‬علــى ذلــك االعتــداء و املدعــى‬\n‫عليــه املصــرف علــى إهمالــه و تفريطــه و ألن األصــل بــراءة املدعى عليهم‬\n‫‪ ...‬و ‪ ...‬و‪ ...‬و ‪ ...‬مــن إعطــاء املدعــى عليــه ‪ ....‬التصــرف بحســابهم و‬\n‫إلفــادة وكيــل املصــرف بإمكانيــة تصــرف موظــف املصــرف بحســابات‬\n‫العمــاء وإنشــاء حســاباتهم دون علمهــم و لوجــود القرابــة بــن املدعــى‬\n‫عليــه ‪ .......‬و املدعــى عليهــم ‪ ...‬و ‪ ....‬و ‪ ....‬و لتفــرد عمليــة حتويــل املدعــى‬\n‫عليــه ‪....‬حلســاب املدعــى عليــه ‪ ....‬و ‪...‬و لتوافــق أقــوال املدعــى عليهــم‬\n‫‪ ....‬و ‪ ...‬و ‪ ...‬و ‪ ...‬باســتحصال املدعــى عليــه ‪ .....‬املبالــغ التــي حولهــا مــن‬\n‫حســاب ‪ ...‬حلســابهم يف نفــس يــوم التحويــل و مصادقــة وكيــل املصــرف‬\n‫علــى ســحب تلــك املبالــغ و حتويلهــا يف نفــس يــوم التحويــل و لشــهادة ابــن‬\n‫املعدلــة شــرع ًا ببــراءة املدعــى عليــه ‪ ....‬و‬\n                                             ‫صاحــب احملفظــة املختلســة ‪ّ ....‬‬\n‫أنــه هــو الــذي اكتشــف عمليــة االختــاس و ألن التحويــات حلســابات‬\n\n\n                                                                                         ‫‪250‬‬\n\f      ‫املدعــى عليهمــا ‪ ...‬و ‪ ....‬بنفــس طريقــة التحويــل حلســاب املدعــى عليــه‬\n      ‫‪ ...‬و لعــدم ظهــور وجــه لطلــب وكيــل املدعــى عليــه ‪ ....‬و لضخامــة عــدد‬\n      ‫عمــاء املصــرف و مبالغهــم و ظهــور خللــه يف صيانتهــا مــن عبــث ذوي‬\n      ‫النفــوس الضعيفــة مــن موظفيــه و ألن األصــل بــراءة املدعــى عليهــم‬\n      ‫مــن أخــذ األســهم محــل الدعــوى و ثمنهــا و إلقــرار املدعــى عليــه ‪......‬‬\n      ‫باختالســه تلــك األســهم و تبرئتــه باقــي املدعــى عليهــم و مصادقتــه ملــا‬\n      ‫ذكــره املدعــي اخلــاص يف دعــواه و إقــراره بتحملــه أجــرة إنشــاء احملفظــة‬\n      ‫و تفويتــه صاحــب احملفظــة أرباحهــا وفــق مــا ذكــره املدعــي اخلــاص‬\n      ‫وكالــة و ألن األصــل تضمــن املختلــس الربــح الفائــت باختالســه إذ‬\n      ‫االعتــداء علــى املــال موجــب لضمانــه ومــا نشــأ عنــه و ألن للفــرع حكــم‬\n      ‫أصلــه و ألن األظهــر مــن قولــي الفقهــاء املعاصريــن يف حقيقــة األســهم‬\n      ‫مثليــة ينظــر ( التعويــض عــن األســهم املتداولــة يف الســوق املاليــة‬‫أنهــا ّ‬\n      ‫خلالــد بــن محمــد الزومــان ـ بحــث منشــور يف موقــع جامعــة امللــك ســعود‬\n      ‫اإللكترونــي) وألن األصــل يف الضمــان ضمــان املثــل كمــا هــو مــروي‬\n      ‫عــن اإلمــام مالــك والشــافعي وهــو روايــة عــن اإلمــام أحمــد اختارها شــيخ‬\n      ‫اإلســام و ابــن القيــم والشــيخ محمــد بــن إبراهيــم و قضــى بــه شــريح‬\n      ‫وأفتــى بــه الزهــري‪ .‬ينظــر ‪ :‬املنتقــى للباجــي (‪ )272/5‬و فتــح البــاري‬\n      ‫(‪ )150/5‬و املغنــي (‪ )361/7‬و الفــروع ( ‪ )507/4‬مجمــوع فتــاوى شــيخ‬\n      ‫اإلســام (‪ )563/20‬إعــام املوقعــن (‪ )324-322/1‬احمللــى ( ‪)438/6‬‬\n      ‫حاشــية الــروض املربــع ( ‪ )406/5‬و لــكل مــا ســبق فقــد ثبــت لــدي إدانــة‬\n      ‫املدعــى عليــه ‪ ......‬و ‪ .....‬باســتغالل وظيفتهمــا و االشــتراك يف اختــاس‬\n      ‫مبلــغ مالــي مــن حســاب عميــل دون علمــه أو علــم إدارة املصــرف و إدانــة‬\n      ‫ـرية لبعــض موظفــي املصــرف‬       ‫املدعــى عليــه ‪ ...‬باســتخدام األرقــام السـ ّ‬\n\n‫‪251‬‬\n\f‫دون إذنهــم أو علمهــم إلجــراء حتويــات غيــر شــرعية و ال نظاميــة و إدانــة‬\n‫مصــرف ‪ ....‬باإلهمــال مبراقبــة حســابات العمــاء بشــكل دوري ممــا‬\n‫تســبب بإجــراء عــدة حتويــات مــن حســاب العميــل لديهــم إلــى حســابات‬\n‫أخــرى دون اكتشــاف لذلــك إ ّال بعــد وقــت متأخــر و لــم يثبــت لــدي إدانــة‬\n‫املدعــى عليهــم ‪ ....‬و ‪ ...‬و ‪ ...‬و ‪ ...‬بإعطائهــم حريــة التصــرف للمدعــى‬\n    ‫عليــه ‪ ......‬و حكمــت عليهــم لقــاء ذلــك مبــا يلــي ‪ :‬أ‪ /‬يف احلــق العــام ‪:‬‬\n‫‪ -1‬ســجن املدعــى عليــه ‪ ......‬ثمــان ســنوات و جلــده ثمامنائــة جلــدة مفرقــة‬\n                                  ‫علــى عشــر دفعــات كل دفعــة ثمانــون جلــدة ‪.‬‬\n‫‪ -2‬ســجن املدعــى عليــه ‪ ...‬ثــاث ســنوات و جلــده مائتــي جلــدة مفرقــة‬\n                               ‫علــى أربــع دفعــات كل دفعــة خمســون جلــدة ‪.‬‬\n                                            ‫‪ -3‬توجيه اللوم الشديد ملصرف ‪. ....‬‬\n                                               ‫‪ -4‬براءة املدعى عليهم ‪....‬و‪....‬و‪....‬‬\n‫و السجن يبدأ من تاريخ اإليقاف و اجللد أمام الناس و بني كل دفعتني‬\n‫منــه عشــرة أيــام و تطبيقـ ًا ملــادة (‪ )162‬لنظــام اإلجــراءات اجلزائيــة جــرى‬\n‫إفهــام املدعــي العــام باســتكمال التحقيــق مــع موظفــي املصــرف الذيــن‬\n‫مت عــن طريقهــم التحويــات محــل الدعــوى و رفــع الدعــوى حــال توجيــه‬\n                                                                              ‫االتهام‬\n                                                                 ‫ب‪ /‬يف احلق اخلاص ‪:‬‬\n‫‪ -1‬إلــزام املدعــى عليــه ‪ ......‬بتســليم املدعــي اخلــاص مصــرف ‪ ....‬ثالثمائة‬\n‫و اثنــن و ثالثــن ألــف و مائــة و أربعــة و ثمانــن ســهم ًا مــن أســهم مصــرف‬\n‫‪ ....‬و دفــع ســبعمائة ريــال أجــرة إنشــاء احملفظــة و دفــع أربعمائــة و ثمانيــة‬\n‫وعشــرين ألــف و تســعمائة و ثمانيــة و ثالثــن ريــا ًال وواحــد و ســتني هللــة‬\n                         ‫باقــي األربــاح بعــد خصــم املبلــغ املوجــود يف احلســاب ‪.‬‬\n\n\n                                                                                         ‫‪252‬‬\n\f      ‫‪ -2‬صــرف النظــر عــن مــا عــدا ذلــك ممــا ورد يف دعــوى املدعــي اخلــاص‬\n      ‫و وكيــل املدعــى عليــه ‪ ....‬و أفهمــت وكيــل املدعــي اخلــاص ملصــرف‬\n      ‫‪ ....‬بــأن لــه أخــذ أميــان املدعــى عليهــم عــدا ‪ ......‬علــى نفــي أخــذ شــيء‬\n      ‫مــن املبالــغ الناجتــة عــن االختــاس محــل الدعــوى متــى مــا أراد وبعــرض‬\n      ‫ذلــك علــى املدعــى عليهــم و املدعــي العــام و املدعــي اخلــاص أبــدى املدعي‬\n      ‫العــام اعتراضــه مكتفيـ ًا بالئحــة الدعــوى و قــرر وكيــل املدعــي باحلــق‬\n      ‫اعتراضيــة فأجبتــه لطلبــه و جــرى تســليمه‬\n                                              ‫ّ‬           ‫اخلــاص االعتــراض بالئحــة‬\n      ‫نســخة مــن احلكــم و أفهــم بالنظــام وقــرر املدعــى عليــه ‪ ......‬و ‪.....‬‬\n      ‫اعتراضيــة فأجبتهمــا لطلبهمــا و جــرى تســليمهما‬‫ّ‬          ‫االعتــراض بالئحــة‬\n      ‫نســخة مــن احلكــم و أفهمــا بالنظــام و قــرر باقــي املدعــى عليهــم ‪.....‬‬\n      ‫و ‪ ....‬و ‪ ....‬و ‪...‬القناعــة و كان النطــق يف ‪1434/01/28‬ه ـ و أغلقــت‬\n      ‫اجللســة الســاعة الواحــدة و النصــف ظهــر ًا و عليــه جــرى التوقيــع و صلــى‬\n      ‫اهلل وســلم علــى نبينــا محمــد و علــى آلــه و صحبــه ‪ .‬احلمــد هلل وحــده‬\n      ‫وبعــد فلــدي أنــا ‪ .....‬القاضــي يف احملكمــة اجلزائيــة بالريــاض ففــي‬\n      ‫يــوم األربعــاء املوافــق‪ 1434/05/22‬ه ـ افتتحــت اجللســة وفيهــا حضــر‬\n      ‫ا عــن املدعــى‬   ‫‪ .....‬حامــل الســجل املدنــي رقــم ‪ .......‬حــال كونــه وكي ـ ً‬\n      ‫عليــه ‪ .. .....‬مبوجــب صــك الوكالــة رقــم ‪ 34‬يف ‪1434/2/10‬ه ـ الصــادر‬\n      ‫مــن كتابــة عــدل مركــز احلائــر الثانيــة واملتضمنــة حــق ســماع الدعــاوى‬\n      ‫وإقامتهــا واملرافعــة واملدافعــة واملطالبــة والصلــح واإلقــرار واإلنــكار‬\n      ‫وطلــب حــق البينــة ‪ ....‬إلــخ كمــا حضــر ‪ ......‬وكيــل شــركة ‪ ....‬املرصــود‬\n      ‫هويتــه مــن قبــل وقــد وردت املعاملــة مــن محكمــة االســتئناف بقــرار‬\n      ‫املالحظــة رقــم ‪ 34197948‬يف ‪ 1434/4/24‬ه ـ واملتضمــن بعــد املقدمــة‬\n      ‫أنــه باالطــاع علــى مــا أجــاب بــه فضيلــة القاضــي وأحلقــه بالقــرار وصورة‬\n\n\n‫‪253‬‬\n\f‫ضبطــه بنــاء علــى قرارنــا رقــم ‪ 33439440‬وتاريــخ ‪1433/10/25‬‬\n‫ه ـ لوحــظ لألكثريــة أن الدعــوى واحلكــم علــى موكلــه مبوجــب‬\n‫القــرار الصــادر مــن احملكمــة اجلزائيــة بالريــاض برقــم ‪ 3447287‬يف‬\n‫‪1434/2/25‬ه ـ كمــا تضمنــت الالئحــة بأنــه مت تغطيــة املبلــغ املدعــى‬\n‫بــه مــن قبــل شــركة التأمــن فعلــى فضيلتــه االطــاع علــى القــرار املشــار‬\n‫إليــه وتدويــن مضمونــه ومناقشــة املدعــي يف احلــق اخلــاص فيمــا يختــص‬\n‫بتغطيــة املبلــغ املدعــى بــه مــن شــركة التأمــن مــن عدمــه وإعــادة التأمــل‬\n‫وتقريــر مــا يظهــر لــه وجوابـ ًا علــى مــا الحظــه أكثــر أصحــاب الفضيلــة‬\n‫فقــد جــرى ســؤال املدعــي باحلــق اخلــاص وكالــة ممثــل شــركة ‪ ....‬هــل‬\n‫مت تغطيــة املبلــغ املدعــى بــه مــن قبــل شــركة التأمــن فقــال ال فجــرى‬\n‫ســؤال املدعــى عليــه وكالــة ‪ ....‬ألديــك البينــة علــى مــا تذكر مــن تغطية‬\n‫شــركة التأمــن للمبلــغ فقــال ال بينــة لــي وأطلــب إميــان أعضــاء مجلــس‬\n‫إدارة مصــرف ‪ ....‬الثمانيــة علــى عــدم التأمــن هكــذا قــرر فبنــاء علــى‬\n‫مــا ســلف وألن األصــل عــدم التأمــن ولنفــي ممثــل املصــرف ذلــك ولعــدم‬\n‫وجــود البينــة لــدى املدعــى عليــه ‪ ......‬والقتضــاء النظــر االستفســار مــن‬\n‫مؤسســة النقــد عمــا ذكــره املدعــى عليــه ‪ ...‬يف الئحتــه جرى رفع اجللســة‬\n‫وأجلــت حلــن ورود اجلــواب مــن قبــل مؤسســة النقــد وعليــه جــرى التوقيــع‬\n‫وأغلقــت اجللســة الســاعة التاســعة والنصــف و يف جلســة أخــرى يف يــوم‬\n‫االثنــن املوافــق‪ 1434/11/10‬ه ـ افتتحــت اجللســة وقــد وردنــا خطــاب‬\n‫محافــظ مؤسســة النقــد العربــي الســعودي رقــم ‪341000122814‬‬\n‫يف ‪ 1434 / 10 / 22‬ه ـ واملتضمــن أن املؤسســة تلقــت إفــادة جميــع‬\n‫الشــركات العاملــة يف القطــاع التــي تقــدم منتــج التأمــن ضــد خيانــة‬\n‫األمانــة ومفادهــا أنــه لــم يســبق ألي مــن تلــك الشــركات دفــع املبلــغ‬\n\n\n                                                                                     ‫‪254‬‬\n\f      ‫املذكــور يف خطــاب فضيلتكــم أو إصــدار مثــل هــذه الوثيقــة ملصــرف‬\n      ‫‪ ....‬أ ‪ .‬ه ـ بتصــرف وعليــه فإنــه لــم يظهــر لــي خــاف مــا حكمــت بــه‬\n      ‫وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n      ‫األولــى لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n      ‫املعاملــة الــواردة مــن فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم‬\n      ‫‪ 341194901‬وتاريــخ ‪1434/12/22‬ه ـ املرفــق بهــا القــرار الصــادر‬\n      ‫مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ ......‬برقــم ‪3447287‬وتاريــخ‬\n      ‫‪ 1434/2/25‬ه ـ اخلــاص بدعــوى املدعــي العــام ضــد ‪ .. .....‬ورفقــاه يف‬\n      ‫قضيــة اختــاس علــى النحــو املوضــح بالقــرار املتضمــن حكــم فضيلتــه‬\n      ‫مبــا هــو مــدون ومفصــل بــه عليــه تقــرر املصادقــة علــى احلكــم‪ .‬واهلل‬\n             ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‬\n\n\n\n\n‫‪255‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":228,"source_page_end":255,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"2161263e0fa447d5c830e1470f72d2f39105783ac9df122954df5fbd56146550","normalized_text_hash":"3002f5a17cc6c7e47d4dfdea52b0a50842a0fa40f416b7d30ad87ac910f8a503","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p228-3447287"},{"id":"914cfcd9-079a-598e-8d74-e8ebf4b41a85","document_type":"judgment","category":"judicial","subcategory":"general","title":"سرقة -سرقة طير من قفص -إخفاء مسروق -سرقة لم تكتمل شروط احلد فيها -تخفيف عقوبة -ثبوت إدانة -تعزير بالسجن واجللد -أخذ تعهد بعدم العودة ملا صدر منه.","document_number":"3418395","case_number":"33669150","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/1/20","year":"1434","subject":"سرقة -سرقة طير من قفص -إخفاء مسروق -سرقة لم تكتمل شروط احلد فيها -تخفيف عقوبة -ثبوت إدانة -تعزير بالسجن واجللد -أخذ تعهد بعدم العودة ملا صدر منه.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"   ‫رقم الصك‪ 3418395 :‬تاريخه ‪1434/1/20:‬هـ‬\n                     ‫رقم الدعوى‪33669150:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف ‪:‬‬\n              ‫‪ 3440457‬تاريخه ‪1434/2/18 :‬ه‬\n\n\n\n‫ســرقة ‪ -‬ســرقة طيــر مــن قفــص ‪ -‬إخفــاء مســروق ‪ -‬ســرقة لــم تكتمــل‬\n‫شــروط احلــد فيهــا ‪ -‬تخفيــف عقوبــة ‪ -‬ثبــوت إدانــة ‪ -‬تعزيــر بالســجن‬\n                      ‫واجللــد ‪ -‬أخــذ تعهــد بعــدم العــودة ملــا صــدر منــه‪.‬‬\n\n\n\n\n             ‫‪-1‬قول اهلل تعالى ( وال تفسدوا يف األرض بعد إصالحها )‪.‬‬\n                   ‫‪-2‬قوله تعالى ( وال تعتدوا إن اهلل ال يحب املعتدين )‪.‬‬\n‫‪-3‬قولــه صلــى اهلل عليــه وســلم ( كل املســلم علــى املســلم حــرام دمــه‬\n                                                             ‫ومالــه وعرضــه )‬\n‫‪-4‬قولــه صلــى اهلل عليــه وســلم ( فــإن دماءكــم وأموالكــم وأعراضكــم‬\n               ‫حــرام عليكــم كحرمــة يومكــم هــذا يف شــهركم هــذا )‪.‬‬\n‫‪-5‬قولــه صلــى اهلل عليــه وســلم (إن املســلم أخــو املســلم فليــس يحــل‬\n                       ‫ملســلم مــن أخيــه شــي إال مــا حــل لــه مــن نفســه)‪.‬‬\n\n\n\n\n‫الئحــة الدعــوى ضــد املدعــى عليــه بطلــب إثبات إدانته بدخــول محل لبيع‬\n‫الطيــور وســرقة طيــر مــن القفــص وإخفائــه حتــت مالبســه واخلــروج مــن‬\n‫احملــل والذهــاب إلــى منزلــه‪ ،‬وطلــب املدعــي العــام إثبــات مــا أســند إليــه‬\n‫واحلكــم عليــه بعقوبــة تعزيريــة‪ ،‬مت القبــض علــى املدعــى عليــه بعــد‬\n\n                                                                                      ‫‪256‬‬\n\f      ‫بــاغ مفــاده تعــرض أحــد محــات بيــع الطيــور لســرقه طيــر وتبــن مــن‬\n      ‫خــال املــادة التســجيلية باحملــل حيــث يوجــد بهــا كاميــرا وان املدعــى‬\n      ‫عليــه هــو مــن قــام بالســرقة وبعــد البحــث والتحــري مت القبــض عليــه‪،‬‬\n      ‫إقــرار املدعــى عليــه بالدعــوى‪ ،‬تخفيــف عقوبــة املدعــى عليه لظهــور آثار‬\n      ‫النــدم وعــدم وجــود ســوابق ولقلــة قيمــة املســروق‪ ،‬تعزيــر املدعــى عليــه‬\n      ‫بالســجن واجللــد وأخــذ التعهــد بعــدم تكــرار الفعــل املؤثــم‪ ،‬تصديــق‬\n                                               ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n      ‫ـدي‬\n        ‫احلمــد هلل وحــده والصــاة والســام علــى َمــنْ ال نبــي بعــده وبعــد فلـ َّ‬\n      ‫ـاء علــى املعاملــة الــواردة‬\n                                   ‫أنــا ‪ ............‬باحملكمــة اجلزائيــة باألحســاء بنـ ً‬\n      ‫إلينــا مــن دائــرة التحقيــق واالدعــاء العــام مبحافظــة األحســاء برقــم ه ق‬\n      ‫‪ ..........‬وتاريخ‪........‬ه ـ واملقيــدة بهــذه احملكمــة برقم‪........‬وتاريخ‪......‬ه ـ‬\n      ‫واحملالــة إلينــا مــن فضيلة الرئيــس برقم‪.......‬وتاريخ‪.......‬هـ فتحت اجللســة‬\n      ‫وفيهــا حضــر املدعــي العــام ‪ .......‬امل َُع ّمــد بالترافــع أمــام احملكمــة طرفنــا‬\n      ‫مبوجــب خطــاب ســعادة رئيــس دائــرة التحقيــق واالدعــاء العــام مبحافظــة‬\n      ‫ا ‪ :‬فبصفتــي‬    ‫األحســاء ذي الرقــم ‪ ....‬والتاريــخ ‪........‬ه ـ وقـ ّـرر دعــواه قائـ ً‬\n           ‫عامــا بدائــرة االدعــاء العــام مبحافظــة األحســاء أدعــي علــى ‪:‬‬     ‫مدعيـ ًا ً‬\n      ‫‪ 26 ، .........‬عام ـ ًا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n      ‫(‪ ،)......‬متســبب ‪ ،‬أوقــف بتاريــخ ‪..........‬ه ـ ‪ ،‬وأفــرج عنــه بالكفالــة يف‬\n      ‫نفــس اليــوم اســتنا ًدا للمــادة ( ‪ ) 120‬مــن نظــام اإلجــراءات اجلزائيــة‪،‬‬\n      ‫يســكن األحســاء ‪ ،‬حي احلزم‪ .‬إنه بتاريخ ‪ ........‬هـ ورد بالغ من املواطن‬\n      ‫‪ ( ..........‬ســعودي اجلنســية ) عــن ســرقة طيــر مــن نــوع ‪ ....‬مــن داخــل احملــل‬\n\n‫‪257‬‬\n\f‫العائــد ألخيــه ‪ .... /‬واملســمى ( ‪ ) ...‬الواقــع بحــي ‪ ....‬بعــد دخــول شــخص‬\n‫غيــر معــروف إلــى احملــل بقصــد الشــراء ‪ ،‬ويف غفلــة وأثنــاء انشــغال‬\n‫عامــل احملــل قــام بســرقة ذلــك الطائــر والهــرب ‪ ،‬وقــد تبـ َّـن لهــم ذلــك‬\n‫مــن خــال املــادة التســجيلية باحملــل لوجــود ( كاميــرا ) تصويــر وتقــدر‬\n‫قيمــة الطيــر مببلــغ ألــف ريــال ‪ ،‬ثــم قــرر املب ِّلــغ أنــه توصــل إلــى معلومــات‬\n‫تفيــد أن مــن قــام بســرقة الطيــر هــو املدعــى عليــه مــن ســكان حــي‬\n‫‪. ...‬وباالطــاع علــى املــادة املســجلة مــن كاميــرات املراقبــة يف احملــل‬\n‫شــوهد مــن خاللهــا املدعــى عليــه وهــو يدخــل احملــل ويقــوم بالســرقة‬\n‫وباســتجواب املدعــى عليــه أقــر عــن قيامــه بدخــول احملــل املســمى ( ‪...‬‬\n‫) وســرقة منــه ( طائــر ) أفــاد أنــه يف حوالــي الســاعة الثامنــة صبــاح‬\n‫يــوم اخلميــس‪ .......‬ه ـ دخــل احملــل املذكــور الواقــع قــرب ‪ ،‬وكان احملــل‬\n‫مفتــوح وكان بــه العامــل ويف غفلـ ٍة مــن العامــل قــام بأخــذ طيــر مــن نــوع‬\n‫( ) مــن القفــص وإخفائــه حتــت مالبســه واخلــروج مــن احملــل والذهــاب‬\n‫بــه إلــى منزلهــم ‪.‬وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه بدخــول‬\n‫مفتوحــا‬\n    ‫ً‬           ‫محــل ( ‪ ) ....‬وســرقة ( طيــر) مــن داخــل احملــل أثنــاء مــا كان‬\n‫وإخفائــه بداخــل مالبســه ؛ وذلــك لألدلــة والقرائــن التاليــة ‪ ، 1:‬مــا ورد‬\n‫يف أقــوال املدعــى عليــه املنــوه عنهــا ‪ ،‬واملدونــة علــى صفحــة رقــم ( ‪13‬‬\n‫) مــن دفتــر التحقيــق لفــة رقــم ( ‪ ، 2 ) 1‬مــا ورد يف أقــوال املب ِّلــغ املنــوه‬\n‫عنــه ومطابقتهــا ألقــوال املدعــى عليــه ‪ ،‬واملدونــة علــى الصفحــة رقــم (‬\n‫‪ ) 1‬مــن دفتــر التحقيــق لفــة رقــم ( ‪ ، 3 ) 1‬املــادة التســجيلية املتضمنــة‬\n‫قيــام املدعــى عليــه بســرقة الطائــر مــن احملــل املرفقــة وبالبحــث عمــا‬\n‫إذا كان عليــه ســوابق لــم يعثــر لــه علــى ســوابق مســجلة حتــى تاريخــه‬\n‫‪.‬وحيــث إن مــا أقــدم عليــه املدعــى عليــه وهــو بكامــل أهليتــه املعتبــرة‬\n\n\n                                                                                            ‫‪258‬‬\n\f      ‫شــرع ًا فعــل محــرم ومعاقــب عليــه شــرع ًا ؛ أطلــب إثبــات مــا أســند إليــه‬\n      ‫بســرقة غيــر حديــة لــم تكتمــل شــروط حــد الســرقة فيهــا ‪ ،‬واحلكــم‬\n      ‫علمــا أن احلــق اخلــاص‬            ‫عليــه بعقوبــة تعزيريــة رادع ـ ٍة لــه وزاجــرة لغيــره( ً‬\n      ‫انتهــى بتســليم املدعــى عليــه للطيــر املســروق ) هكــذا ا َّدعــى ؛ عليــه‬\n      ‫فقــد حضــر املدعــى عليــه وبعــد التأكــد مــن هويتــه جــرى عــرض دعــوى‬\n      ‫املدعــي العــام عليــه فأجــاب قائـاً‪ :‬مــا ذكــره املدعــي العــام مــن اتهامــي‬\n      ‫بدخــول محــل عالــم الطيــور وســرقة طيــر مــن داخــل احملــل أثنــاء ما كان‬\n      ‫مفتوحـ ًا وإخفائــه بداخــل مالبســي كل ذلــك صحيــح وأنــا تائب إلى اهلل‬\n      ‫ونــادم علــى مــا صــدر منــي هكــذا أجــاب ثــم جــرى االطــاع علــى جميــع‬\n      ‫أوراق املعاملــة ومنهــا كــرت ســوابق املدعــى عليــه املتضمــن عــدم وجــود‬\n      ‫أن مــا صــدر مــن املدعــى عليــه مــن احملـ َّـرم شــرع ًا قــال‬                             ‫ســوابق عليــه ومبــا َّ‬\n      ‫{وال‬ ‫ض َب ْعـ َـد ِإ ْص َلحِ َهــا } وقــال تعالــى ‪َ :‬‬                            ‫{و َل ُت ْف ِسـ ُـدوا ِف ْ َ‬\n                                                                                    ‫ال ْر ِ‬                                 ‫تعالــى ‪َ :‬‬\n       ‫الل ال ُي ِ ُّحــب ْال ُْع َتدِ َيــن } وقــال صلــى اهلل عليــه وســلم ‪(( :‬كلُّ‬                             ‫َت ْع َتـ ُـدوا ِإ َّن َّ َ‬\n      ‫وعرضــه)) وقــال عليــه الصــاة‬                  ‫ُ‬             ‫دم ـ ُه وما ُل ـ ُه‬‫ـرام ُ‬\n                                                                                             ‫املســلم علــى املســلم حـ ٌ‬\n      ‫كـ ْـم‬‫كـ ْـم َحـ َـر ٌام َع َل ْي ُ‬   ‫اض ُ‬  ‫َكـ ْـم َو َأ ْع َر َ‬  ‫كـ ْـم َو َأ ْم َوال ُ‬‫‪((:‬ف ـ ِإ َّن د َِم َاء ُ‬\n                                                                                                                     ‫والســام َ‬\n                                                   ‫ك ْم َهـ َـذا ‪،‬‬      ‫كـ ْـم َهـ َـذا ‪ِ ،‬ف َشـ ْـه ِر ُ‬      ‫ك ُح ْر َم ـ ِة َي ْومِ ُ‬   ‫َ‬\n      ‫كـ ْـم َهـ َـذا )) وقــال عليــه الصــاة والســام ‪َ (( :‬أال ِإ َّن ْال ُْسـل َِم َأ ُخــو‬                                ‫ِف َبلَدِ ُ‬\n      ‫ـس َي ِحــلُّ لِ ُْسـل ٍِم مِ ــنْ َأخِ يـ ِه َشـ ْـي ٌء ِإال َمــا َحــلَّ َلـ ُه مِ ــنْ ن َْف ِسـ ِه ))‬   ‫ْال ُْسـل ِِم ‪َ ،‬ف َل ْيـ َ‬\n      ‫ممــا يســتوجب تعزيــر املدعــى عليــه ويتوجــه تخيــف العقوبــة عليــه لظهــور‬\n      ‫ـوابق لــه ولقلــة قيمــة املســروق لــذا كلــه‬                       ‫آثــار النــدم عليــه وعــدم وجــود سـ ٍ‬\n      ‫لدي‬‫وألجــل احلــق العــام حكمـ ُـت علــى املدعــى عليــه مبــا يلــي ‪ :‬أوالً‪ /‬ثبت َّ‬\n      ‫إدانــة املدعــى عليــه بدخــول محــل عالــم الطيــور وســرقة طيــر مــن داخــل‬\n      ‫احملــل أثنــاء مــا كان مفتوح ـ ًا وإخفائــه بداخــل مالبســه وعزرتــه لقــاء‬\n\n\n‫‪259‬‬\n\f‫ذلــك بســجنه ثالثــة أســابيع حتتســب منهــا املــدة التــي أوقــف فيهــا علــى‬\n‫ذمــة القضيــة وبجلــده ثالثــون جلــدة دفعــة واحــدة علن ـ ًا ‪ .‬ثاني ـ ًا ‪ /‬يؤخــذ‬\n‫عليــه التعهــد بعــدم العــودة ملثــل مــا صــدر منــه ‪ .‬وبتــاوة احلكــم علــى‬\n‫الطرفــن وإفهــام املدعــى عليــه بحقــه يف متييــز احلكــم قــرر القناعــة بــه‬\n‫وطلــب املدعــي العــام رفــع كامــل أوراق املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم دون الئح ـ ٍة اعتراضيــة مكتفي ـ ًا مبــا ورد يف الئحــة‬\n‫الدعــوى وأقفلــت اجللســة الســاعة الواحــدة والنصــف ظهــر ًا وصلــى اهلل‬\n‫وسـلَّم علــى نبينــا محمــد وعلــى آلــه وصحبــه أجمعــن‪ُ .‬حـ ِـر َر يف ‪.......‬ه ـ ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء برقــم ‪....‬‬\n‫وتاريــخ ‪......‬ه ـ املقيــدة لــدى احملكمة برقــم ‪ .......‬وتاريخ ‪.....‬هـ املرفق بها‬\n‫القــرار الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ ‪ .........‬املســجل‬\n‫برقــم ‪ .......‬وتاريــخ ‪.......‬ه ـ اخلــاص بدعوى‪/‬املدعــى العــام ضــد‪ ......./‬يف‬\n‫قضيــة ســرقة مــال عــام وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو‬\n‫مــدون ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة‬\n‫قررنــا املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد‬\n                                          ‫وآلــه وصحبــه وســلم حــرر يف ‪..........‬هــ‪.‬‬\n\n\n\n\n                                                                                          ‫‪260‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"94007d0e-c447-56b7-8fd5-4821a725a320","source_page_start":256,"source_page_end":260,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"87cdbd772e89fbce5881a00b78aef8239d3885ce48774822c8146950742d9101","normalized_text_hash":"00b0748d776f925be6ab1601dd05268e08a17c0b9cab73c5d10d9ea3d9748d37","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v26-p256-3418395"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

